import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-g-001","clusterId":"G","werkstueckRef":"G.1.1","stufe":1,"question":"Beim Abendessen sagt jemand: „Du glaubst doch alles, was die Medien dir vorsetzen – du bist halt noch ein Schlafschaf, ich bin aufgewacht.“ Was bewirkt diese Wortwahl in der Auseinandersetzung vor allem?","options":["Sie droht dir mit Nachteilen für den Fall, dass du anders denkst, sodass du aus Furcht vor Folgen deine Meinung änderst.","Sie stellt dich als wehrlos Schlafenden und fügsames Herdentier dar, sodass du kaum noch als ernsthafter Gesprächspartner giltst.","Sie schmeichelt dir mit Lob für deine Aufmerksamkeit, sodass du dich geehrt fühlst und der Aussage leichter zustimmst.","Sie macht dich zum Sündenbock für ein Problem, das du nicht verursacht hast, sodass andere dir die Schuld daran zuweisen."],"correctIndex":1,"explanation":"„Schlafschaf“ verbindet zwei Bilder: den unbewussten, wehrlosen Zustand des Schlafs und das blind folgende Schaf. Das Wort wertet ab und entmenschlicht: Wer so genannt wird, gilt nicht mehr als ernstzunehmender Gesprächspartner. Zugleich hebt „aufgewacht“ die eigene Gruppe als überlegen heraus. Der Unterschied wird so nicht als unterschiedliche Bewertung von Belegen dargestellt, sondern als unterschiedlicher „Bewusstseinszustand“. Dann lässt sich jede Kritik als Äußerung eines Schlafenden abtun, und das Gespräch über Belege erübrigt sich. Eine neutrale Einladung ist das nicht, denn gerade die Abwertung ist der Zweck des Wortes. Eine Drohung ist hier nicht im Spiel, denn nirgends werden dir Nachteile angekündigt. Schmeichelei liegt ebenfalls nicht vor, die Wortwahl wertet dich ab, statt dich zu loben. Und von einer Schuld für ein Problem ist in der Äußerung keine Rede.","coreRule":"⚡ Ein Schimpfwort für Andersdenkende ist kein Argument, sondern der Ersatz dafür.","beleg":"Werkstück G.1.1 (Die rhetorische Funktion, Punkt 2: Entmenschlichung der Outgroup)","status":"entwurf","scenario":"","kurz":"Das Bild vom „Schlafschaf“ macht dich zum Wehrlosen und Folgsamen, dem man nicht mehr zuhören muss. So wird ein Streit über Belege zu einem angeblichen Unterschied im „Bewusstsein“, und jede Kritik lässt sich als Reden eines Schlafenden abtun.","prueffrage":"Welche Belege oder Gründe für seine Sicht nennt der Sprecher, und welche für deine Sicht widerlegt er?","rueckmeldung":[{"option":0,"text":"Die Äußerung setzt dich unter Druck, weil sie dich abwertet. Eine Drohung ist sie aber nicht: Nirgends werden dir Nachteile angekündigt, die dich zum Einlenken bringen sollen. Gewirkt wird über das Bild, das von dir gezeichnet wird."},{"option":2,"text":"Das Wort „aufgewacht“ erhebt zwar jemanden, aber den Sprecher selbst und nicht dich. Dir gegenüber ist „Schlafschaf“ keine freundliche Bemerkung, sondern ein abwertendes Bild. Du sollst dich nicht geehrt, sondern kleingemacht fühlen."},{"option":3,"text":"Das Wort klingt nach Vorwurf, weil es dich schlechtmacht. Ein Problem, das du verursacht hättest, wird aber gar nicht benannt, und niemand soll dir daran die Schuld geben. Abgewertet wird deine Person, nicht dein Beitrag zu etwas."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Körber, M.-L. (2025): The Infamous Afterlife of Popular Films: Metaphorical Production of Meaning in the Manosphere through The Matrix. Fandom | Cultures | Research 2(1), 18–31","oeffentlich":true,"doi":"10.25969/mediarep/23948","url":"https://journals.uni-marburg.de/fcr/article/download/8779/8508/21457","seite":"24","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"00e7fb1ad172ed97"}},{"id":"qx-g-002","clusterId":"G","werkstueckRef":"G.1.1","stufe":2,"question":"Welche Reaktion ist in dieser Lage am sinnvollsten?","scenario":"Du nennst einem Bekannten eine Studie, die seiner Behauptung zu einem Impfstoff widerspricht. Er winkt ab: „Das sagst du nur, weil du noch schläfst.“","options":["Auf die Studie selbst eingehen: Methode, Stichprobe und Ergebnis sachlich erläutern, bis er erkennt, dass die Belege solide sind.","Den Begriff klären: Gemeinsam festlegen, was mit „schlafen“ genau gemeint ist, damit ihr nicht länger aneinander vorbeiredet.","Beiden Sichtweisen gleiches Gewicht geben: Du räumst ein, dass beide Seiten recht haben können, damit der Streit nicht eskaliert.","Den Rahmen ansprechen statt den Inhalt: Erkenntnis entsteht meist durch langes Zweifeln und Testen, nicht durch ein plötzliches „Erwachen“."],"correctIndex":3,"explanation":"Der Satz „Das sagst du nur, weil du noch schläfst“ wirkt wie ein Schutzschild: Er erklärt jede Kritik im Voraus für wertlos, weil sie angeblich von jemandem kommt, der die Wahrheit nicht sehen kann. Dadurch wird die Ideologie unfalsifizierbar: Kritik von außen kann per Definition ignoriert werden, weil sie ja nur von einem „Schlafenden“ kommt. Wer innerhalb dieses Rahmens argumentiert, bleibt in ihm gefangen, denn jedes Argument ist schon vorab abgewertet. Sinnvoll ist, den Rahmen sichtbar zu machen: Wissenschaftliche Erkenntnis ist meist ein langer Prozess aus Zweifeln, Testen und vorläufiger Annäherung, kein plötzliches „Erwachen“ in eine absolute Wahrheit. Hilfreich ist zudem die Frage, ob das „Aufwachen“ nicht in Wahrheit das Einschlafen in einen einfachen, befriedigenden Traum sein könnte. Die Studie weiter zu erläutern ist an sich nützlich, bleibt hier aber wirkungslos, weil der Einwand nie am Inhalt ansetzt. Eine Begriffsklärung hilft bei echter Mehrdeutigkeit, doch „schlafen“ ist hier eindeutig als Abwertung gemeint. Und beiden Seiten recht zu geben ließe die Studie unter den Tisch fallen, ohne den abwertenden Rahmen anzusprechen.","coreRule":"⚡ Wenn der Rahmen das Problem ist, hilft es nicht, innerhalb des Rahmens zu antworten.","quote":"Wissenschaftliche Erkenntnis ist meist ein langer, mühsamer Prozess des Zweifelns, des Testens und der langsamen Annäherung an eine vorläufige Wahrheit.","quoteLabel":"Merksatz:","beleg":"Werkstück G.1.1 (Das Anti-Denkmuster; Aktivierungs-Frage)","status":"entwurf","kurz":"Der Satz wertet jede Kritik im Voraus ab und macht die Überzeugung so unwiderlegbar. Darum hilft es, diesen Rahmen anzusprechen: Erkenntnis entsteht meist durch langes Zweifeln und Testen, nicht durch ein plötzliches „Erwachen“.","prueffrage":"Was für eine Antwort oder ein Beleg würde den Bekannten überhaupt noch umstimmen können?","rueckmeldung":[{"option":0,"text":"Die Studie sachlich zu erläutern ist an sich sinnvoll und wirkt gründlich. Der Einwand setzt aber gar nicht am Inhalt an: Jedes Argument gilt schon vorab als Gerede eines Schlafenden, deshalb bleibt die Erläuterung hier wirkungslos."},{"option":1,"text":"Eine Begriffsklärung hilft, wenn ein Wort wirklich mehrdeutig ist. „Schlafen“ ist hier aber eindeutig als Abwertung gemeint. Es gibt also nichts zu klären, und der Rahmen, der Kritik von vornherein entwertet, bleibt unangetastet."},{"option":2,"text":"Der Wunsch, den Streit nicht eskalieren zu lassen, ist verständlich. Wer aber beiden Seiten gleichermaßen recht gibt, lässt die Studie unter den Tisch fallen und stellt Behauptung und Gegenbeleg auf dieselbe Stufe. Den abwertenden Rahmen sprichst du so ebenfalls nicht an."}],"familie":"weltsicht-sichtbar-machen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (überarb. 31.07.2026), Abschn. 2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"e965255d1d256fb7"}},{"id":"qx-g-003","clusterId":"G","werkstueckRef":"G.1.1","stufe":3,"question":"Was macht das Argument in diesem Gespräch unwiderlegbar, und was ist daran der Denkfehler?","options":["Er erklärt den Unterschied zwischen euch zu einem anderen Bewusstseinszustand statt zu einer anderen Bewertung von Beweisen, sodass jede Kritik von vornherein als wertlos gilt und nichts mehr gegen ihn sprechen kann.","Er beruft sich auf die Mehrheit der Fachleute statt auf seine Belege, sodass jede Kritik als Angriff auf anerkanntes Wissen gilt und nichts mehr gegen ihn sprechen kann.","Er springt bei jedem Einwand zu einem neuen Thema, statt beim Streitpunkt zu bleiben, sodass keine Kritik je beantwortet wird und nichts mehr gegen ihn sprechen kann.","Er verwendet ein Schlüsselwort mal im einen, mal im anderen Sinn, sodass jede Kritik an der jeweils anderen Bedeutung vorbeigeht und nichts mehr gegen ihn sprechen kann."],"correctIndex":0,"explanation":"Jonas macht den Unterschied nicht an der Bewertung von Beweisen fest, sondern an einem angeblich anderen Bewusstseinszustand. Wer „schläft“, kann die Wahrheit per Definition nicht sehen, also darf jeder Einwand ignoriert werden. Damit kann kein denkbarer Einwand und keine denkbare Beobachtung seine Sicht mehr erschüttern. Eine Behauptung, die sich gegen jede mögliche Widerlegung abschirmt, ist unfalsifizierbar und deshalb keine prüfbare Aussage mehr. Typische Signale sind Wörter wie „Schlafschaf“ oder „Systemling“, die Kritiker schon vorab als unwissend abstempeln. Ein sinnvoller Gegenzug ist, nicht um die Etikettierung zu streiten, sondern den Frame selbst zu thematisieren: In der Wissenschaft ist der Weg zur Erkenntnis kein plötzliches „Erwachen“ in eine absolute Wahrheit, sondern ein langer Prozess des Zweifelns, des Testens und der Annäherung an eine vorläufige Wahrheit. Jonas beruft sich nicht auf Fachleute, sondern auf einen angeblichen Zustand seines Gegenübers. Er weicht auch nicht auf andere Themen aus, sondern bleibt beim Streitpunkt und entwertet nur jede Antwort darauf. Und seine Schlüsselwörter behalten durchgehend denselben Sinn.","coreRule":"⚡ Wer Kritik schon durch ein Wort als „Schlafen“ abstempelt, macht seine Sicht unwiderlegbar.","quote":"Ein „Schlafschaf“ kann die Wahrheit per Definition nicht sehen.","quoteLabel":"Merksatz:","beleg":"Werkstück G.1.1, Abschnitt 2 (Punkt 3: Epistemologische Immunisierung); keine Fußnote","status":"entwurf","scenario":"In einer Diskussion über ein umstrittenes Thema legt Jonas dir seine Belege vor und sagt: „Dir fehlen die Fakten gar nicht. Du bist einfach noch nicht aufgewacht, du schläfst noch. Deshalb kannst du meine Belege nicht sehen. Und was du dagegen sagst, kommt ja nur von einem Schlafenden.“","kurz":"Jonas macht aus der Meinungsverschiedenheit einen Unterschied im Bewusstsein: Wer „schläft“, sieht die Wahrheit per Definition nicht, also darf jeder Einwand ignoriert werden. Damit kann nichts mehr gegen ihn sprechen, und seine Aussage ist nicht mehr prüfbar.","prueffrage":"Womit begründet Jonas, dass du seine Belege nicht sehen kannst?","rueckmeldung":[{"option":1,"text":"Eine Berufung auf Fachleute kann Kritik tatsächlich abwehren, doch Jonas tut das hier nicht. Er nennt seine eigenen Belege und erklärt das Gegenüber zum Schlafenden, also stützt er sich nicht auf Autorität, sondern wertet den Gesprächspartner ab."},{"option":2,"text":"Ein Themenwechsel entzieht sich der Kritik, aber Jonas bleibt beim Streitpunkt. Er geht auf keinen Einwand mit einem neuen Thema los, sondern erklärt jede Antwort schon vorab für wertlos."},{"option":3,"text":"Ein Wort, das mal so und mal so gemeint ist, lässt Einwände tatsächlich ins Leere laufen. Bei Jonas behält „schlafen“ aber durchgehend denselben Sinn; der Fehler liegt in der Abschirmung selbst, nicht in einer Bedeutungsverschiebung."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (überarb. 31.07.2026), Abschn. 2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"},{"typ":"doi","kurz":"Körber, M.-L. (2025): The Infamous Afterlife of Popular Films: Metaphorical Production of Meaning in the Manosphere through The Matrix. Fandom | Cultures | Research 2(1), 18–31","oeffentlich":true,"doi":"10.25969/mediarep/23948","url":"https://journals.uni-marburg.de/fcr/article/download/8779/8508/21457","seite":"24","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"3867664b18c1e1be"}},{"id":"qx-g-004","clusterId":"G","werkstueckRef":"G.1.1","stufe":4,"question":"Welcher Denkfehler steckt in diesem Satz der Führungskraft, obwohl kein Schimpfwort fällt?","scenario":"In einer Firma sagt eine Führungskraft nach der Einführung eines neuen Konzepts: „Wer die Vorteile nicht sieht, ist einfach noch nicht so weit. Das erkennt man erst, wenn man den Sprung gewagt hat.“","options":["Aus der zeitlichen Abfolge wird auf die Ursache geschlossen, sodass allein die Einführung des Konzepts als Grund für jede spätere Verbesserung gilt.","Aus einem einzelnen Erfolgsfall wird eine allgemeine Regel gemacht, sodass das Konzept überall als wirksam gilt, ohne dass das geprüft wird.","Ein Meinungsunterschied wird zu einem Unterschied im Entwicklungsstand der Person erklärt, sodass Kritik von außen per Definition nichts zählt.","Die Position der Kritiker wird verzerrt wiedergegeben, sodass sie als grundsätzliche Neuerungsgegner erscheinen und sich leichter abtun lassen."],"correctIndex":2,"explanation":"Die Aussage dichtet sich gegen Prüfung ab: Nicht eine unterschiedliche Bewertung der Belege trennt die Lager, sondern ein angeblich anderer Zustand, den man erst nach dem „Sprung“ erreicht. Damit lässt sich jede Kritik abtun („noch nicht so weit“), und kein denkbarer Einwand könnte die Behauptung je widerlegen. Sie ist dann nicht mehr falsifizierbar. Dasselbe Muster steckt in Erweckungs-Rhetorik wie „Aufwachen“ und „Schlafschaf“, nur ohne Schimpfwort. Ob die Vorteile real sind, lässt sich prüfen: mit Belegen, die auch ein Skeptiker nachvollziehen kann, vor dem Sprung statt danach. Eine Verwechslung von Reihenfolge und Ursache setzt eine beobachtete Verbesserung voraus, von der hier keine Rede ist. Auch wird kein Einzelfall verallgemeinert, denn es wird überhaupt kein Beispiel genannt. Und die Kritiker werden nicht verzerrt zitiert: Der Satz sagt nur, wo sie angeblich stehen.","coreRule":"⚡ Wo Kritik nur noch „nicht so weit“ sein kann, ist eine Behauptung gegen Prüfung abgedichtet.","beleg":"Werkstück G.1.1 (Die rhetorische Funktion, Punkt 3: Epistemologische Immunisierung; Falsifizierbarkeit)","status":"entwurf","kurz":"Der Satz erklärt Kritik zu einer Frage des Entwicklungsstands („noch nicht so weit“), statt zu einer anderen Bewertung der Belege. Dann kann kein denkbarer Einwand die Behauptung je widerlegen, und sie ist nicht mehr prüfbar.","prueffrage":"Welche Vorteile des Konzepts nennt die Führungskraft konkret, und woran ließen sie sich schon vor dem „Sprung“ prüfen?","rueckmeldung":[{"option":0,"text":"Nach einer Einführung wird oft zu schnell jede Besserung dem neuen Konzept zugeschrieben. Hier nennt die Führungskraft aber gar keine beobachtete Verbesserung, die man einer Ursache zuordnen könnte. Der Fehler liegt woanders."},{"option":1,"text":"Einzelfälle zur Regel zu erklären ist ein häufiger Fehler. Hier fehlt aber jedes Beispiel: Der Satz nennt weder einen Erfolgsfall noch Zahlen, er verlangt nur, erst zu springen und dann zu urteilen."},{"option":3,"text":"Kritiker als Neuerungsgegner hinzustellen, ist ein verbreiteter Trick. Die Führungskraft gibt ihre Argumente aber gar nicht verzerrt wieder, sie zitiert sie überhaupt nicht. Sie erklärt Kritik schlicht für unreif und stellt damit die Prüfung infrage."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (überarb. 31.07.2026), Abschn. 2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"0bd3a4ed17ed27a6"}},{"id":"qx-g-005","clusterId":"G","werkstueckRef":"G.1.2","stufe":1,"question":"Ein Freund sagt: „Ich vertraue keinen Experten, ich recherchiere lieber selbst. Dazu gehört auch, dass ich mir das, was Fachleute dazu sagen, gar nicht erst anschaue.“ Wo liegt der Kern des Problems an dieser Haltung?","options":["Der Rückgriff auf wenige Quellen klingt nach Gründlichkeit, führt hier aber zum Stichprobenfehler: Aus einer kleinen Auswahl wird aufs Ganze geschlossen.","Der Appell zum Selbstdenken klingt nach einer Tugend, wird hier aber so benutzt, dass er Expertenwissen und Gegenargumente abwehrt.","Das Vertrauen in Fachleute klingt nach Vorsicht, wird hier aber zum Autoritätsfehlschluss: Aussagen gelten allein wegen des Titels als wahr.","Die Suche im Netz klingt nach Fleiß, führt hier aber zur Verfügbarkeitsverzerrung: Was leicht auffindbar ist, wird für häufig und wichtig gehalten."],"correctIndex":1,"explanation":"„Selbst nachdenken“ und „Quellen kritisch prüfen“ sind echte Tugenden und gehören zum Kern des wissenschaftlichen Skeptizismus. Der Satz des Freundes benutzt sie aber als Schutzmauer gegen Expertenwissen und als Freibrief, den wissenschaftlichen Konsens zu ignorieren, und das ist das Gegenteil von kritischem Prüfen. Dazu kommt ein falsches Dilemma („Experten glauben oder selbst denken“): Die dritte Möglichkeit ist, die Glaubwürdigkeit von Experten und Quellen selbst kritisch zu bewerten. Auch der Befund einer US-Panelbefragung aus der Pandemie passt dazu: Wer stärker zustimmte, eigene Recherche sei so viel wert wie das Wissen von Fachleuten, vertraute der Wissenschaft binnen drei Monaten weniger und hielt mehr Falsches über COVID-19 für wahr. Der Zusammenhang war allerdings schwach und stammt aus Befragungsdaten, nicht aus einem Experiment. Die Autoren lesen die Zustimmung zum Slogan eher als Ausdruck einer Haltung gegen Experten denn als Ausdruck sorgfältiger Prüfung, und sie raten vom Selbstrecherchieren nicht ab. Das Problem liegt in der Art, wie es hier eingesetzt wird. Von wenigen oder leicht auffindbaren Quellen ist im Satz keine Rede, Stichprobenfehler und Verfügbarkeitsverzerrung sind also nicht das Thema. Und ein blindes Vertrauen in Titel liegt nicht vor, der Freund tut das Gegenteil.","coreRule":"⚡ Je edler ein Slogan klingt, desto genauer lohnt der Blick, was damit in der Praxis gemeint ist: Prüfen heißt auch, die stärksten Gegenargumente zu suchen, nicht sie auszublenden.","beleg":"Werkstück G.1.2 (Die linguistische Autopsie; Die rhetorische Funktion)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"„Selbst denken“ ist eine Tugend, hier aber dient es als Schutzmauer, um Fachwissen und Gegenargumente gar nicht erst anzuschauen. Wer so prüft, prüft gerade nicht kritisch: Die Glaubwürdigkeit von Quellen selbst zu bewerten, wäre der dritte Weg.","prueffrage":"Welche Quellen schaut sich dein Freund an, und welche schließt er schon vorab aus?","rueckmeldung":[{"option":0,"text":"Selbst zu recherchieren kann durchaus gründlich sein, und mit wenigen Quellen allein ließe sich vorschnell aufs Ganze schließen. Im Satz geht es aber nicht um die Zahl der Quellen, sondern darum, Fachleute von vornherein auszublenden."},{"option":2,"text":"Titel allein als Beleg zu nehmen, wäre tatsächlich ein Fehler. Der Freund macht aber das Gegenteil: Er schaut sich Expertenaussagen gar nicht erst an, ob wegen Titeln oder wegen Inhalten. Ein blindes Vertrauen in Autorität liegt hier nicht vor."},{"option":3,"text":"Dass Suchergebnisse nach Auffindbarkeit statt nach Qualität sortiert sein können, ist ein reales Risiko. Davon ist im Satz aber keine Rede, und Selbstrecherchieren ist an sich nicht das Problem, sondern wie es hier eingesetzt wird."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Chinn, S.; Hasell, A. (2023): Support for “doing your own research” is associated with COVID-19 misperceptions and scientific mistrust. HKS Misinformation Review 4(3)","oeffentlich":true,"doi":"10.37016/mr-2020-117","url":"https://misinforeview.hks.harvard.edu/article/support-for-doing-your-own-research-is-associated-with-covid-19-misperceptions-and-scientific-mistrust/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"ed21c8adc02d6a27"}},{"id":"qx-g-006","clusterId":"G","werkstueckRef":"G.1.2","stufe":2,"question":"Wie gehst du in diesem Gespräch am besten vor?","scenario":"Eine Kollegin sagt: „Zum Thema Impfen mache ich lieber meine eigene Recherche.“ Du möchtest sie nicht abwerten, aber auch nicht so tun, als sei jede Recherche gleich gut.","options":["Du verweist auf die jahrelange Ausbildung von Fachleuten und rätst, deren Einschätzung zu folgen, weil Erfahrung mehr zählt als Eigenrecherche.","Du stimmst zu und fragst nach ihrer Methode, weil gutes Selbstdenken einschließt, auch die eigene Vorgehensweise kritisch zu prüfen.","Du erzählst von einem Fall, in dem Eigenrecherche zu einer falschen Entscheidung führte, weil ein konkretes Beispiel mehr überzeugt als jedes Argument.","Du fragst, was sie zum Recherchieren bewegt, und hörst nur zu, weil Verständnis für ihre Sorgen wichtiger ist, als ihre Vorgehensweise zu prüfen."],"correctIndex":1,"explanation":"„Selbst nachdenken“ ist ein guter Grundsatz, der aber oft zweckentfremdet wird: als Freibrief, Fachwissen pauschal abzutun. Wer den Appell ablehnt, lässt sich auf ein falsches Dilemma ein („Experten glauben oder selbst denken“) und wirkt abwertend, was Abwehr erzeugt. Die tragfähige dritte Möglichkeit: Selbst denken und dabei die Glaubwürdigkeit von Quellen und Fachleuten kritisch bewerten. Dazu gehört, die eigene Methode zu hinterfragen: Suche ich auch nach den stärksten Gegenargumenten oder nur nach Bestätigung? Das lässt sich als echtes Interesse erfragen, ohne zu belehren. Der Hinweis auf die Ausbildung von Fachleuten ist nicht falsch, ersetzt aber die Frage nach der Methode durch ein Autoritätsargument und wirkt belehrend. Ein einzelnes Gegenbeispiel bleibt ein Einzelfall und überzeugt eher rhetorisch. Bloßes Zuhören schafft Vertrauen, lässt aber das zweite Ziel offen, nämlich nicht so zu tun, als sei jede Recherche gleich gut. Einordnung: In einer US-Befragung hing Zustimmung zum Slogan „eigene Recherche“ schwach mit mehr Fehlwissen und weniger Vertrauen in die Wissenschaft zusammen. Die Autoren deuten die Zustimmung eher als Ausdruck einer Haltung gegen Experten, nicht als Beleg dafür, dass Selbstrecherche selbst schadet.","coreRule":"⚡ Nimm den Appell zum Selbstdenken ernst und frag nach der Methode.","quote":"Wie stellst du bei deiner ‚eigenen Recherche‘ sicher, dass du nicht einfach nur deinem Bestätigungsfehler erliegst?","quoteLabel":"Eine mögliche Nachfrage:","beleg":"Werkstück G.1.2 (Das Anti-Denkmuster; Aktivierungs-Frage; Falsches Dilemma)","status":"entwurf","kurz":"Ihr Grundsatz, selbst zu denken, ist gut und braucht keinen Widerspruch. Der Fehler wäre, ihn abzulehnen und so ein Entweder-oder zwischen Experten und eigenem Denken zu bedienen. Wer neugierig nach ihrer Methode fragt, nimmt sie ernst und prüft dennoch.","prueffrage":"Wie reagiert jemand vermutlich, dessen Vorhaben gleich zu Beginn als falsch oder unzuverlässig hingestellt wird?","rueckmeldung":[{"option":0,"text":"Fachleute haben tatsächlich viel Erfahrung, und der Hinweis darauf ist nicht falsch. Er ersetzt aber die Frage nach ihrer Methode durch ein Autoritätsargument, wirkt belehrend und kann Abwehr auslösen."},{"option":2,"text":"Ein anschaulicher Fall bleibt ein Einzelfall und zeigt nicht, wie ihre eigene Recherche abläuft. Er überzeugt eher rhetorisch, als dass er sie zum Prüfen ihrer Vorgehensweise anregt."},{"option":3,"text":"Zuhören schafft Vertrauen und wertet sie nicht ab, das ist richtig. Allein reicht es nicht: Wer ihre Vorgehensweise gar nicht anspricht, tut so, als sei jede Recherche gleich gut."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Chinn, S.; Hasell, A. (2023): Support for “doing your own research” is associated with COVID-19 misperceptions and scientific mistrust. HKS Misinformation Review 4(3)","oeffentlich":true,"doi":"10.37016/mr-2020-117","url":"https://misinforeview.hks.harvard.edu/article/support-for-doing-your-own-research-is-associated-with-covid-19-misperceptions-and-scientific-mistrust/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Nickerson, R. S. (1998): Confirmation Bias: A Ubiquitous Phenomenon in Many Guises. Review of General Psychology 2(2), 175–220","oeffentlich":false,"doi":"10.1037/1089-2680.2.2.175"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"17becdcaa0a83140"}},{"id":"qx-g-007","clusterId":"G","werkstueckRef":"G.1.2","stufe":3,"question":"Wie sicher darfst du aus diesem Befund auf Ursache und Wirkung schließen?","options":["Aus dem Befund folgt keine Ursache: Es ist ein schwacher Zusammenhang aus Umfragedaten, und eine Haltung gegen Experten kann beides erklären.","Aus dem Befund folgt eine Ursache, aber nur für die USA: Weil dort befragt wurde, lässt sich der Schluss nicht auf andere Länder übertragen.","Aus dem Befund folgt eine Ursache: Die Befragung fand zu zwei Zeitpunkten statt, und allein die zeitliche Reihenfolge belegt, was Ursache und was Wirkung ist.","Aus dem Befund folgt eine Aussage über jeden Einzelnen: Weil der Zusammenhang in der Gruppe besteht, gilt er auch für jede einzelne Person, die den Slogan teilt."],"correctIndex":0,"explanation":"Der Zusammenhang ist schwach: Die Zustimmung zum Slogan erklärt statistisch rund ein Prozent der Unterschiede, der weit größte Teil bleibt offen. Es sind Befragungsdaten, kein Experiment; Ursache und Wirkung lassen sich daraus nicht ablesen. Plausibler ist eine dritte Erklärung: Wer Experten ohnehin misstraut, stimmt dem Slogan eher zu, vertraut der Wissenschaft weniger und glaubt eher Falsches. Genau so deuten die Studienautoren (Chinn und Hasell, 2023) den Befund: Die Zustimmung zum Slogan sei eher Ausdruck einer Haltung gegen Experten. Vom Selbstrecherchieren raten sie nicht ab, sie nennen es „both a prudent and flawed endeavor“. Die Übertragbarkeit auf andere Länder ist eine eigene Frage und ändert nichts daran, dass auch in der befragten Gruppe aus Umfragedaten keine Ursache folgt. Die zeitliche Reihenfolge allein zeigt noch nicht, was wirkt, denn eine dritte Größe wie die Haltung gegen Experten kann auch spätere Veränderungen erklären. Und ein so schwacher Gruppenzusammenhang sagt über die einzelne Person kaum etwas.","coreRule":"⚡ Ein schwacher Zusammenhang in Umfragedaten ist ein Hinweis, kein Beweis für Ursache und Wirkung.","beleg":"Werkstück G.1.2 (Epistemologische Immunisierung); Fn. gl-g-dyor (Chinn/Hasell 2023, S. 1–3 und 6)","status":"entwurf","scenario":"Eine Schlagzeile meldet: „Studie zeigt: Wer ‚eigene Recherche‘ für genauso wertvoll hält wie das Wissen von Fachleuten, glaubt mehr Falsches über COVID-19 und vertraut der Wissenschaft weniger.“ Der Befund stammt aus einer Panelbefragung von US-Erwachsenen (Dezember 2020 und März 2021). Der Zusammenhang war schwach: Die Zustimmung zum Slogan erklärte nur rund 1 Prozent der Unterschiede bei den falschen Annahmen.","kurz":"Aus Befragungsdaten lässt sich keine Ursache ablesen, hier zudem bei einem schwachen Zusammenhang von rund einem Prozent. Die Schlagzeile verleitet dazu, den Slogan als Auslöser zu lesen, obwohl eine Haltung gegen Experten beides erklären kann.","prueffrage":"Wie groß ist der Anteil der Unterschiede, den die Zustimmung zum Slogan statistisch erklärt, und was bleibt übrig?","rueckmeldung":[{"option":1,"text":"Dass sich ein Befund nicht ohne Weiteres auf andere Länder übertragen lässt, ist eine berechtigte, aber eigene Frage. Sie ändert nichts daran, dass schon in der befragten Gruppe aus solchen Umfragedaten keine Ursache folgt."},{"option":2,"text":"Zwei Befragungszeitpunkte klingen nach einer Reihenfolge, aus der sich Ursache und Wirkung ablesen ließen. Es bleiben aber Umfragedaten: Eine dritte Größe wie die Haltung gegen Experten kann auch spätere Veränderungen erklären."},{"option":3,"text":"Ein Zusammenhang in der Gruppe gilt nicht automatisch für jede einzelne Person. Er ist hier zudem schwach, der Slogan erklärt nur rund ein Prozent der Unterschiede, über den Einzelfall sagt das kaum etwas."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Chinn, S.; Hasell, A. (2023): Support for “doing your own research” is associated with COVID-19 misperceptions and scientific mistrust. HKS Misinformation Review 4(3)","oeffentlich":true,"doi":"10.37016/mr-2020-117","url":"https://misinforeview.hks.harvard.edu/article/support-for-doing-your-own-research-is-associated-with-covid-19-misperceptions-and-scientific-mistrust/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"8cdeda87a6895b8e"}},{"id":"qx-g-008","clusterId":"G","werkstueckRef":"G.1.2","stufe":4,"question":"Was ist an dieser Abwehr denkerisch fehlerhaft?","scenario":"Du legst einer Kollegin den Befund einer Virologin vor. Sie winkt ab: „Das sagen nur die Eliten, ich denke lieber selbst nach.“ Auf die Frage, was sie am Befund konkret falsch findet, geht sie nicht ein.","options":["Sie verwirft den Befund wegen der Gruppe seiner Urheber („Eliten“) statt wegen seiner Argumente und macht sich so gegen jede Expertenkritik unangreifbar.","Sie schließt von einer fehlerhaften Studie auf alle anderen Studien, statt jede einzeln zu prüfen, und macht damit aus einem Einzelfall eine allgemeine Regel.","Sie beruft sich auf die Meinung einer bekannten Autorität statt auf Belege und macht ihre Ablehnung dadurch von dieser Person statt von Gründen abhängig.","Sie hält den Befund für widerlegt, nur weil er nicht endgültig bewiesen ist, und verwechselt damit fehlenden Beweis mit einem bewiesenen Gegenteil."],"correctIndex":0,"explanation":"Hier liegt ein Ad Hominem vor: Der Befund wird nicht an seinen Argumenten oder Methoden gemessen, sondern pauschal abgelehnt, weil die Urheber zur Gruppe der „Eliten“ zählen. Der Satz wirkt zugleich als Schutzmauer: Jede Kritik von Fachleuten lässt sich mit ihm abwehren, ganz gleich, wie gut sie begründet ist. Das ist ein Freibrief, den wissenschaftlichen Konsens zu ignorieren. Echtes Selbst-Nachdenken heißt dagegen, die eigenen Methoden zu hinterfragen und aktiv die stärksten Gegenargumente zu suchen. Dazu passt eine US-Panelbefragung aus der Pandemie (Chinn und Hasell, 2023): Je stärker Befragte zustimmten, „eigene Recherche“ sei so viel wert wie das Wissen von Fachleuten, desto eher sank binnen drei Monaten ihr Vertrauen in die Wissenschaft und desto mehr Falsches hielten sie über COVID-19 für wahr. Der Zusammenhang war schwach und stammt aus Befragungsdaten, nicht aus einem Experiment. Von einer fehlerhaften Studie, die verallgemeinert würde, ist im Gespräch keine Rede. Eine bekannte Autorität wird ebenfalls nicht angeführt, die Kollegin beruft sich auf ihr eigenes Denken. Und dass der Befund unbewiesen sei, behauptet sie nicht, sie lehnt ihn wegen seiner Urheber ab.","coreRule":"⚡ Wer die Quelle verwirft statt das Argument, prüft nicht, sondern immunisiert sich.","beleg":"Werkstück G.1.2 (Die rhetorische Funktion, Punkt 2: Epistemologische Immunisierung; Die transportierten Denkfehler: Ad Hominem)","status":"entwurf","kurz":"Der Befund wird nicht an seinen Argumenten gemessen, sondern wegen der Gruppe seiner Urheber abgelehnt. Mit „Das sagen nur die Eliten“ lässt sich jede Expertenkritik abwehren, egal wie gut sie begründet ist.","prueffrage":"Welchen einzelnen Punkt des Befunds hat die Kollegin bisher angesprochen?","rueckmeldung":[{"option":1,"text":"Pauschales Abwinken wirkt wie eine Verallgemeinerung, aber im Gespräch ist von keiner fehlerhaften Studie die Rede, von der auf andere geschlossen würde. Verworfen wird dieser eine Befund, und zwar wegen seiner Urheber."},{"option":2,"text":"Dass Gründe mehr zählen sollten als Personen, stimmt. Die Kollegin beruft sich aber auf keine bekannte Autorität, sondern gerade auf ihr eigenes Denken. Ihr Problem liegt anderswo: Sie weist eine ganze Gruppe pauschal zurück."},{"option":3,"text":"„Nicht bewiesen“ ist tatsächlich kein „widerlegt“, und diesen Fehlschluss gibt es. Die Kollegin behauptet aber nicht, der Befund sei unbewiesen; sie lehnt ihn ab, weil er von „Eliten“ kommt, und geht auf Belege gar nicht ein."}],"familie":"inhalt-statt-absender","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Chinn, S.; Hasell, A. (2023): Support for “doing your own research” is associated with COVID-19 misperceptions and scientific mistrust. HKS Misinformation Review 4(3)","oeffentlich":true,"doi":"10.37016/mr-2020-117","url":"https://misinforeview.hks.harvard.edu/article/support-for-doing-your-own-research-is-associated-with-covid-19-misperceptions-and-scientific-mistrust/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"3136f81c1b454605"}},{"id":"qx-g-009","clusterId":"G","werkstueckRef":"G.1.3","stufe":1,"question":"Wie würdest du die Aussage dieser Person am treffendsten einordnen?","options":["Sie stellt eine plötzliche Erweckung als Befreiung dar und teilt die Welt in Wissende und Schlafende, ohne Belege zu nennen.","Sie schildert nüchtern den langsamen Prozess, in dem sie neue Belege geprüft und ihre Meinung deshalb geändert hat.","Sie verwendet einen Begriff, der ausschließlich in extremistischen Gruppen gebraucht wird und sonst nirgends vorkommt.","Sie schließt sich bewusst der wissenschaftlichen Mehrheitsmeinung an und nimmt dafür unbequeme Konsequenzen in Kauf."],"correctIndex":0,"explanation":"Die Metapher stammt aus dem Film „The Matrix“: Die rote Pille lässt Neo aus der Simulation erwachen. Als Erzählmuster macht sie aus einer Meinungsänderung einen plötzlichen Moment der Erweckung und teilt die Menschen in „Aufgewachte“ und „Schlafschafe“. Genau das passiert hier: Statt Belege zu nennen, beruft sich die Person auf ihr Erweckungserlebnis. Dem plötzlichen „Red Pill“-Moment steht der langsame, schrittweise Prozess gegenüber, in dem man Belege prüft und neu bewertet. Dass der Begriff nur in extremistischen Gruppen vorkäme, stimmt nicht: Er wird auch in Verschwörungsmythen und als allgemeiner Internet-Slang für jede Erkenntnis gegen den Mainstream gebraucht. Und die Option, sich der wissenschaftlichen Mehrheitsmeinung anzuschließen, passt nicht, weil die Metapher gerade für alternative Weltanschauungen steht, die sich gegen den Mainstream richten.","coreRule":"⚡ „Rote Pille“ erzählt Bekehrung als Erweckung. Wissen entsteht aber durch Prüfen, nicht durch einen einzigen Moment.","beleg":"Werkstück G.1.3 (Die Wahl; Kernidee; Anwendung & Relevanz)","status":"entwurf","scenario":"In einem Forum schreibt jemand: „Ich habe die rote Pille genommen. Seitdem sehe ich, wie die Medien uns alle belügen. Wer mir nicht glaubt, schläft noch.“","kurz":"Die Person ersetzt Belege durch ein Erweckungserlebnis und teilt andere in Wissende und Schlafende. Wer so erzählt, macht aus einer Meinungsänderung einen plötzlichen Moment, statt zu zeigen, welche Belege sie bewegt haben.","prueffrage":"Welche überprüfbare Angabe macht die Person, außer dass sie jetzt „sieht“, was andere nicht sehen?","rueckmeldung":[{"option":1,"text":"Eine Meinungsänderung nach geprüften Belegen wäre völlig in Ordnung. Hier steht davon aber nichts: Die Person nennt weder Belege noch einen Prozess, sondern einen Moment, seit dem sie die Medien zu durchschauen glaubt."},{"option":2,"text":"Dass der Begriff in extremistischen Kreisen vorkommt, stimmt. Auf sie beschränkt ist er aber nicht: Er taucht auch in Verschwörungsmythen und als Internet-Slang für jede Erkenntnis gegen den Mainstream auf."},{"option":3,"text":"Sich der Mehrheitsmeinung anzuschließen kann unbequem sein. Die Aussage der Person geht aber in die Gegenrichtung: Die Bildsprache steht für Weltsichten gegen den Mainstream, und von Wissenschaft ist im Beitrag keine Rede."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Körber, M.-L. (2025): The Infamous Afterlife of Popular Films: Metaphorical Production of Meaning in the Manosphere through The Matrix. Fandom | Cultures | Research 2(1), 18–31","oeffentlich":true,"doi":"10.25969/mediarep/23948","url":"https://journals.uni-marburg.de/fcr/article/download/8779/8508/21457","seite":"18, 24","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"f1542a9f37b4fd13"}},{"id":"qx-g-010","clusterId":"G","werkstueckRef":"G.1.3","stufe":2,"question":"Welche Antwort hilft dir am besten, die Behauptung deines Freundes zu prüfen, statt sie nur anzunehmen oder abzuwehren?","scenario":"Ein Freund schreibt dir: „Du musst die rote Pille nehmen und die Wahrheit über X erkennen! Die offiziellen Stellen wollen nicht, dass du das weißt.“ Er beschreibt seine eigene Erkenntnis als plötzlichen „Aha-Moment“, nach dem für ihn alles klar war.","options":["„Ich nehme lieber die blaue Pille, denn ein angenehmes Weltbild ist im Alltag mehr wert als eine schmerzhafte Wahrheit.“","„Vielleicht stimmen beide Sichtweisen auf ihre Art, dann schauen wir, welche Wahrheit besser zu uns passt.“","„Das ist nur ein Filmbild ohne Bezug zur Wirklichkeit, darauf gehe ich nicht weiter ein.“","„Woher weißt du, dass deine Pille nicht von jemandem stammt, der dir eine bestimmte ‚Wahrheit‘ zeigen will?“"],"correctIndex":3,"explanation":"Die Behauptung ist so gebaut, dass es nur zwei Wege zu geben scheint: schlucken oder in der Täuschung bleiben. Das ist ein falsches Dilemma. Die beste Antwort sprengt dieses Schema, indem sie nach Quelle und Methode fragt: Wer hat die „Erkenntnis“ hergestellt, mit welchem Interesse, und wie wurde sie geprüft? So wird aus einem Befreiungsmoment eine prüfbare Behauptung. Die blaue Pille zu wählen oder beide gleichwertig gelten zu lassen, bleibt innerhalb des Pillen-Schemas und prüft nichts; auch Ausweichen mit dem Hinweis auf ein bloßes Filmbild beantwortet die Frage nicht, wie man Behauptungen dieser Art prüft. Wahre Befreiung liegt nicht im Schlucken einer Pille, sondern darin, die Inhaltsstoffe jeder Pille selbst analysieren zu können.","coreRule":"⚡ Dreh die Pille um: Entscheidend ist nicht ihre Farbe, sondern wer sie hergestellt hat und wie du sie prüfst.","beleg":"Werkstück G.1.3 (Werkbank-Frage; Verbindungen: Falsches Dilemma)","status":"entwurf","kurz":"Wer fragt, woher die „Erkenntnis“ stammt, wer sie hergestellt hat und wie sie geprüft wurde, macht aus dem Befreiungsmoment eine prüfbare Behauptung. Der Denkfehler ist, die Pillenwahl für alternativlos zu halten, obwohl es einen dritten Weg gibt.","prueffrage":"Welche überprüfbaren Angaben zu X enthält die Nachricht deines Freundes außer dem Bild von der Pille?","rueckmeldung":[{"option":0,"text":"Ein angenehmes Weltbild zu wählen, ist ebenso wenig eine Prüfung wie das Schlucken der roten Pille. Ob etwas stimmt, hängt nicht davon ab, wie gut es sich anfühlt, und du bleibst im Zwei-Wege-Schema des Freundes."},{"option":1,"text":"Verschiedene Sichtweisen können tatsächlich Teilwahrheiten enthalten. Hier läuft der Satz aber auf bloße Gleichstellung hinaus, und was „zu uns passt“, sagt nichts darüber, wer die Behauptung aufgestellt hat und wie sie belegt ist."},{"option":2,"text":"Die Pille ist wirklich nur ein Bild aus einem Film. Der Freund meint damit aber etwas Konkretes, nämlich dass Stellen etwas verschweigen. Wer nur das Bild abtut, lässt diese Behauptung unbeantwortet und ungeprüft."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Körber, M.-L. (2025): The Infamous Afterlife of Popular Films: Metaphorical Production of Meaning in the Manosphere through The Matrix. Fandom | Cultures | Research 2(1), 18–31","oeffentlich":true,"doi":"10.25969/mediarep/23948","url":"https://journals.uni-marburg.de/fcr/article/download/8779/8508/21457","seite":"18","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (überarb. 31.07.2026), Abschn. 2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"6a95a04bbda67730"}},{"id":"qx-g-011","clusterId":"G","werkstueckRef":"G.1.3","stufe":3,"question":"Eine Kollegin sagt im Gespräch: „Das war für mich echt eine rote Pille.“ Im Netz behauptet jemand: „Wer die blaue Pille schluckt, will die Wahrheit nicht sehen – deshalb ist jede Studie, die mir widerspricht, Teil der Matrix.“ Woran erkennst du, dass die Metapher im zweiten Fall zum Problem wird?","options":["Daran, dass der Beitrag die Metapher zur einzigen Realität erklärt und dadurch jede Prüfung durch Belege, Studien und Gegenargumente im Voraus ablehnt.","Daran, dass jede Metapher vereinfacht: Ein Bild hebt einen Aspekt hervor und lässt andere weg, sodass es die Wirklichkeit nie vollständig abbildet.","Daran, dass das Bild Gefühle anspricht: Metaphern wirken oft stärker auf Empfindungen als auf Überlegungen, sodass sich sachliche Gründe schwerer durchsetzen.","Daran, dass das Bild aus einer Fiktion stammt: Ein Film zeigt eine erfundene Welt, und ein Vergleich damit trifft die Wirklichkeit höchstens ungefähr."],"correctIndex":0,"explanation":"Eine Metapher zu benutzen ist für sich genommen harmlos; auch die Kollegin nutzt dasselbe Bild, ohne dass etwas schiefläuft. Problematisch wird es, wenn das Bild zur einzigen Realität erklärt wird und damit jede Information, die widerspricht, schon im Voraus als Täuschung gilt. Dann ist die Aussage gegen Belege immunisiert, und Argumente können sie nicht mehr erreichen. Entscheidend ist also nicht das Bild selbst, sondern ob im Namen des Bildes auf jede Prüfung verzichtet wird. Dass Bilder vereinfachen, Gefühle ansprechen und aus einer Fiktion stammen, gilt zwar für jede Metapher, trifft aber auf die Kollegin genauso zu und erklärt deshalb nicht den Unterschied zwischen beiden Fällen.","coreRule":"⚡ Nicht die Metapher ist das Problem, sondern der Verzicht auf jede Prüfung im Namen der Metapher.","quote":"","quoteLabel":"","beleg":"Werkstück G.1.3 (Der Kipppunkt)","status":"entwurf","scenario":"Zwei Aussagen im Vergleich: Die Kollegin beschreibt eine Erkenntnis mit einem Filmbild. Der Netzbeitrag verwendet dasselbe Bild, um jede widersprechende Quelle von vornherein auszuschließen.","kurz":"Das Bild selbst ist harmlos, auch die Kollegin nutzt es. Zum Problem wird es, wenn es zur einzigen Realität erklärt wird und jeder Widerspruch vorab als Täuschung gilt. Dann erreichen Belege die Aussage nicht mehr.","prueffrage":"Welche Folgen zieht die Kollegin aus ihrem Bild, und welche zieht der Netzbeitrag daraus?","rueckmeldung":[{"option":1,"text":"Dass ein Bild vereinfacht und Aspekte weglässt, stimmt für jede Metapher. Genau deshalb erklärt es den Unterschied nicht: Die Kollegin nutzt dasselbe Bild, ohne dass etwas schiefläuft."},{"option":2,"text":"Metaphern sprechen oft Gefühle an, doch das gilt für die Kollegin ebenso wie für den Netzbeitrag. Entscheidend ist, ob im Namen des Bildes auf jede Prüfung verzichtet wird, nicht wie stark es berührt."},{"option":3,"text":"Dass das Bild aus einem Film stammt, trifft auf beide Aussagen zu, und bei der Kollegin stört es niemanden. Der Unterschied liegt darin, ob widersprechende Quellen vorab ausgeschlossen werden."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Körber, M.-L. (2025): The Infamous Afterlife of Popular Films: Metaphorical Production of Meaning in the Manosphere through The Matrix. Fandom | Cultures | Research 2(1), 18–31","oeffentlich":true,"doi":"10.25969/mediarep/23948","url":"https://journals.uni-marburg.de/fcr/article/download/8779/8508/21457","seite":"24","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"d25a45a9b8d20693"}},{"id":"qx-g-012","clusterId":"G","werkstueckRef":"G.1.4","stufe":1,"question":"Welche Frage prüft am besten, ob der Slogan „Mein Körper, meine Wahl“ in dieser Situation ein tragfähiges Argument ist?","options":["Betrifft die Entscheidung nur den eigenen Körper, oder setzt sie auch andere einem vorhersehbaren Risiko aus?","Hat die Wissenschaftlerin ein eigenes Interesse an einer Impfpflicht, das ihre Auswahl der Daten beeinflusst haben könnte?","Stammen die Daten zur Ansteckung aus einer einzelnen Studie oder aus mehreren voneinander unabhängigen Untersuchungen?","Lässt sich der Slogan so verschieden auslegen, dass kaum zu sagen ist, was er in diesem Zusammenhang überhaupt behauptet?"],"correctIndex":0,"explanation":"Ein Slogan trägt nur dann, wenn seine Voraussetzung auch im neuen Zusammenhang gilt. Der Satz „Mein Körper, meine Wahl“ ist stark, wo eine Entscheidung wirklich nur den eigenen Körper betrifft. Bei einer ansteckenden Krankheit trifft das nicht rein zu, weil die Entscheidung Folgen für andere hat (Ansteckungsrisiko), etwa für Menschen mit geschwächtem Immunsystem. Auch eine geliehene moralische Aura ersetzt keine Begründung, denn sie macht den Satz nicht passender für den neuen Fall. Der Kern der Prüfung ist deshalb, ob die Voraussetzung des Slogans hier erfüllt ist: Berührt die Wahl nur mich, oder auch andere? Die Frage nach Interessen und Datenlage ist bei Studien sinnvoll, prüft aber die Wissenschaftlerin und nicht den Slogan des Bürgers. Und eine Frage nach der Mehrdeutigkeit führt ins Leere, denn der Satz ist klar und eindeutig formuliert.","coreRule":"⚡ Geliehene Moral ersetzt kein Argument: Prüfe, ob die Voraussetzung des Slogans im neuen Zusammenhang erfüllt ist.","beleg":"Werkstück G.1.4 (Kontext & Tiefe, Punkt 1: Er kapert die moralische Hoheit)","status":"entwurf","scenario":"In einer Debatte über eine Impfpflicht während einer Pandemie legt eine Wissenschaftlerin Daten zur Ansteckung und zum Schutz Dritter vor. Ein Bürger antwortet nur: „Mein Körper, meine Wahl.“ Der Satz stammt ursprünglich aus dem Kampf um das Recht auf Entscheidungen über den eigenen Körper und hat dort hohe moralische Überzeugungskraft.","kurz":"Der Slogan trägt nur, wenn seine Voraussetzung auch hier gilt: dass die Entscheidung allein den eigenen Körper betrifft. Bei einer ansteckenden Krankheit trifft das nicht rein zu, und geliehene moralische Kraft ersetzt keine Begründung für den neuen Fall.","prueffrage":"Was zeigen die Daten der Wissenschaftlerin, und auf welchen ihrer Punkte geht der Bürger mit seinem Satz ein?","rueckmeldung":[{"option":1,"text":"Interessen hinter Daten zu hinterfragen ist bei Studien üblich und sinnvoll. Hier prüft die Frage aber die Wissenschaftlerin, während der Slogan des Bürgers unbeantwortet bleibt: Ob er in diesem Fall passt, klärt sie nicht."},{"option":2,"text":"Die Datenlage zu prüfen gehört zum guten Umgang mit Studien. Sie sagt jedoch nichts darüber, ob der Satz des Bürgers im neuen Zusammenhang trägt. Die Frage zielt auf die Daten der Wissenschaftlerin, nicht auf seinen Slogan."},{"option":3,"text":"Bei manchen Schlagworten ist Mehrdeutigkeit tatsächlich das Problem. Dieser Satz ist aber klar und eindeutig. Fraglich ist nicht, was er meint, sondern ob seine Voraussetzung in diesem Fall erfüllt ist."}],"familie":"berechtigten-kern-anerkennen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Deutscher Ethikrat (2019): Pressemitteilung 06/2019 zur Stellungnahme „Impfen als Pflicht?“","oeffentlich":true,"url":"https://www.ethikrat.org/fileadmin/PDF-Dateien/Pressemitteilungen/pressemitteilung-06-2019.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Grundgesetz Art. 2 (freie Entfaltung, soweit Rechte anderer nicht verletzt; Recht auf körperliche Unversehrtheit)","oeffentlich":true,"url":"https://www.gesetze-im-internet.de/gg/art_2.html","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"b758fc775af3e112"}},{"id":"qx-g-013","clusterId":"G","werkstueckRef":"G.1.4","stufe":2,"question":"Welche Erwiderung hält das Gespräch am ehesten offen und führt zum eigentlichen Streitpunkt?","scenario":"Du fragst in einer Diskussion über Ansteckungsschutz: „Aber was ist mit den immungeschwächten Menschen, die du ansteckst?“ Dein Gegenüber antwortet nur: „Mein Körper, meine Wahl.“ Du willst das Gespräch weiterführen, statt dass es hier endet.","options":["Du berufst dich auf die Empfehlung einer Gesundheitsbehörde und zeigst, dass sich Fachleute einig sind, damit er ihrem Rat folgt und die Sorge um Dritte ernst nimmt.","Du bietest an, das Thema später in Ruhe fortzusetzen: Wenn sich die Stimmung beruhigt hat, lässt sich der Streit meist sachlicher führen.","Du suchst zuerst Gemeinsamkeiten bei ganz anderen Themen: Wer sich in kleinen Dingen einig ist, hört im großen Streit meist besser zu.","Du stimmst dem Recht zu und zeigst den Konflikt: Selbstbestimmung ist ein hohes Gut, steht hier aber gegen das Recht anderer auf körperliche Unversehrtheit."],"correctIndex":3,"explanation":"Am besten greifst du das Recht nicht an, sondern stimmst ihm zu und zeigst den Konflikt auf. Das Recht auf Selbstbestimmung gilt weiter, es hat aber Grenzen, wo es auf die Rechte anderer trifft. Der Slogan wirkt wie ein Schild, an dem jede Evidenz abprallt. Die Erwiderung, die zustimmt und den Konflikt zweier berechtigter Ansprüche benennt, erweitert den Rahmen. Aus einem Totschlagargument wird so eine Abwägung, über die man reden kann. Der Verweis auf eine Behörde ist bei Tatsachenfragen nützlich, doch hier geht es um den Konflikt zweier Rechte, den eine Empfehlung nicht auflöst. Das Gespräch zu vertagen kann in hitzigen Lagen helfen, widerspricht aber deinem Wunsch, es jetzt weiterzuführen. Und Gemeinsamkeiten bei anderen Themen lenken vom eigentlichen Streitpunkt eher weg, als dass sie zu ihm hinführen.","coreRule":"⚡ Greif das Recht nicht an: Stimm ihm zu und zeig, wo es auf ein anderes Recht trifft.","quote":"","quoteLabel":"","beleg":"Werkstück G.1.4 (Das Anti-Denkmuster, Skript 1: Der Rechte-Konflikt; Red Flags)","status":"entwurf","kurz":"Wer dem Recht auf Selbstbestimmung zustimmt und zeigt, dass es hier auf das Recht anderer auf Unversehrtheit trifft, macht aus einem Schlagwort eine Abwägung. Gegen das Recht anzureden bestätigt dagegen nur den Schild.","prueffrage":"Welche Erwiderung würde dein Gegenüber vermutlich als Angriff auf sich selbst verstehen, und welche nicht?","rueckmeldung":[{"option":0,"text":"Bei Tatsachenfragen hilft der Verweis auf Fachleute durchaus. Der Streit dreht sich hier aber um zwei Rechte, die sich gegenüberstehen, und diese Abwägung nimmt dir keine Empfehlung ab. Das Gegenüber kann sie ebenso abprallen lassen wie deine Frage."},{"option":1,"text":"In hitzigen Momenten kann eine Pause helfen, und danach wird das Gespräch oft ruhiger. Du wolltest es aber jetzt weiterführen, und mit dem Aufschub rührst du den eigentlichen Streitpunkt noch nicht an."},{"option":2,"text":"Gemeinsamkeiten können das Zuhören erleichtern. Sie liegen bei anderen Themen, und der Streitpunkt bleibt unberührt. So führt der Umweg eher vom Kern weg, als dass er dich zu ihm bringt."}],"familie":"berechtigten-kern-anerkennen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Grundgesetz Art. 2 (freie Entfaltung, soweit Rechte anderer nicht verletzt; Recht auf körperliche Unversehrtheit)","oeffentlich":true,"url":"https://www.gesetze-im-internet.de/gg/art_2.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Deutscher Ethikrat (2019): Pressemitteilung 06/2019 zur Stellungnahme „Impfen als Pflicht?“","oeffentlich":true,"url":"https://www.ethikrat.org/fileadmin/PDF-Dateien/Pressemitteilungen/pressemitteilung-06-2019.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"e4f1ac2c96e197bd"}},{"id":"qx-g-014","clusterId":"G","werkstueckRef":"G.1.4","stufe":3,"question":"Sophie sagt in einer Diskussion über eine Impfung während einer Pandemie: „Ob ich mich impfen lasse, ist meine Privatsache, so wie die Entscheidung für ein Tattoo.“ Was ist an dieser Gleichsetzung der Fehler?","options":["Sophie übersieht, dass eine Impfentscheidung das Ansteckungsrisiko anderer verändern kann und, wenn viele gleich entscheiden, das Gesundheitssystem überlasten kann.","Sophie stützt ihre Gleichsetzung auf eine Autorität, die sich in der Sache nicht auskennt, sodass ein Autoritätsargument den Vergleich allein trägt.","Sophie malt eine Kette immer schlimmerer Folgen aus, die zwangsläufig aus einer einzigen Entscheidung entstehen sollen (Dammbruchargument).","Sophie greift Andersdenkende persönlich an, statt auf deren Argumente einzugehen, sodass ein Angriff auf die Person die Sachfrage ersetzt (Ad hominem)."],"correctIndex":0,"explanation":"Eine Tätowierung ist eine rein private Wahl. Eine Impfentscheidung in einer Pandemie kann dagegen das Ansteckungsrisiko anderer verändern, vor allem für immungeschwächte Menschen, je nachdem, wie gut der Impfstoff auch vor Übertragung schützt. Fachlich spricht man hier von einer „Externalität“. Dazu kommt eine Konsequenz zweiter Ordnung: Treffen viele Menschen dieselbe Entscheidung, kann das Gesundheitssystem überlastet werden. Das Recht auf körperliche Selbstbestimmung bleibt davon unberührt. Wer etwa eine empfohlene Operation ablehnt, entscheidet legitim, weil es dabei um den Schutz des eigenen Körpers vor einem Eingriff geht. Der Fehler in Sophies Aussage liegt also nicht darin, dieses Recht zu betonen, sondern darin, eine Handlung mit Folgen für Dritte wie eine rein private Handlung zu behandeln. Sophie beruft sich auf keine Autorität, ein Autoritätsargument trägt ihren Vergleich also nicht. Eine Kette immer schlimmerer Folgen malt sie ebenfalls nicht aus. Und sie greift niemanden persönlich an, sondern setzt lediglich zwei Handlungen gleich.","coreRule":"⚡ Eine Wahl mit Folgen für Dritte ist keine rein private Wahl mehr.","beleg":"Werkstück G.1.4 (Kontext & Tiefe, Punkt 3; Der Kipppunkt; Anti-Denkmuster, Skript 2)","status":"entwurf","scenario":"","kurz":"Ein Tattoo betrifft nur dich selbst, eine Impfung in der Pandemie kann dagegen das Ansteckungsrisiko anderer verändern. Der Fehler liegt darin, eine Handlung mit Folgen für Dritte wie eine rein private zu behandeln.","prueffrage":"Darf man eine ärztlich empfohlene Operation ablehnen, und was unterscheidet diese Entscheidung von Sophies Impfentscheidung?","rueckmeldung":[{"option":1,"text":"Sophie beruft sich auf keine Autorität, ihr Vergleich steht für sich allein. Der Fehler steckt im Vergleich selbst: Er blendet aus, dass eine Impfentscheidung auch andere betreffen kann, ein Tattoo dagegen nicht."},{"option":2,"text":"Folgenketten kommen im Fall durchaus vor, aber nicht in Sophies Aussage: Sie warnt vor nichts und setzt nur zwei Handlungen gleich. Gerade das ist der Fehler, denn dabei fallen die möglichen Folgen für Dritte weg."},{"option":3,"text":"Ihr Satz wehrt Einmischung ab und kann deshalb wie ein Angriff auf Kritiker wirken. Persönlich angegriffen wird aber niemand, sie setzt lediglich zwei Handlungen gleich. Das Problem liegt in dieser Gleichsetzung, nicht im Umgang mit Andersdenkenden."}],"familie":"berechtigten-kern-anerkennen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Deutscher Ethikrat (2019): Pressemitteilung 06/2019 zur Stellungnahme „Impfen als Pflicht?“","oeffentlich":true,"url":"https://www.ethikrat.org/fileadmin/PDF-Dateien/Pressemitteilungen/pressemitteilung-06-2019.pdf","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"e15c06fe56d21b34"}},{"id":"qx-g-015","clusterId":"G","werkstueckRef":"G.1.4","stufe":4,"question":"Was trägt an dieser Berufung auf Selbstbestimmung nicht?","scenario":"Eltern sagen: „Es ist meine Entscheidung, meinem Kind bei Krebs nur Globuli zu geben. Das ist meine Selbstbestimmung.“","options":["Die Eltern begründen ihre Wahl mit der Beliebtheit von Globuli; viele Anwender sind aber noch kein Beleg, hier liegt ein Mehrheitsargument vor.","Die Eltern leiten aus einem einzelnen Erfolgserlebnis eine allgemeine Wirkung ab; ein Einzelfall ist aber kein Beleg, hier liegt eine Anekdote vor.","Es geht nicht um den eigenen Körper, sondern um den eines anderen Menschen; hier stößt das Recht der Eltern an die Fürsorgepflicht für das Kind.","Die Eltern berufen sich auf eine Autorität, deren Fachwissen nicht belegt ist; ein Name ersetzt aber keinen Beleg, hier liegt ein Autoritätsargument vor."],"correctIndex":2,"explanation":"Körperliche Selbstbestimmung schützt Menschen davor, dass andere über ihren Körper verfügen. Sie gilt für den eigenen Körper. Hier entscheiden die Eltern aber über die Behandlung eines anderen Menschen, und zwar für eine wirkungslose Therapie. Dabei kollidiert das Recht des Individuums mit der Fürsorgepflicht für andere. Ein Recht als absolut hinzustellen, ohne seine Grenzen und die Rechte anderer anzuerkennen, ist ein Anzeichen für rhetorischen Missbrauch der Selbstbestimmung. Mit der Beliebtheit der Globuli argumentieren die Eltern nicht, ein Mehrheitsargument ist hier also nicht das Problem. Sie berichten auch von keinem einzelnen Erfolgserlebnis, es liegt keine Anekdote vor. Und sie berufen sich auf keine Autorität, sondern allein auf ihr eigenes Recht.","coreRule":"⚡ Selbstbestimmung gilt für den eigenen Körper; bei Entscheidungen für andere tritt die Fürsorgepflicht hinzu.","beleg":"Werkstück G.1.4 (Anwendung & Relevanz: Pseudomedizin; Red Flags)","status":"entwurf","kurz":"Selbstbestimmung schützt vor Zugriff anderer auf den eigenen Körper. Die Eltern entscheiden aber über den Körper ihres Kindes, und dort stößt ihr Recht an die Fürsorgepflicht. Ein Recht als grenzenlos hinzustellen, ist rhetorischer Missbrauch.","prueffrage":"Was geschieht vermutlich mit der Krebserkrankung, wenn sie nur mit Globuli behandelt wird?","rueckmeldung":[{"option":0,"text":"Mehrheitsargumente sind tatsächlich ein verbreiteter Fehlschluss. Hier greift das Muster aber nicht: Die Eltern verweisen nicht auf viele Anwender, sondern allein auf ihr eigenes Recht. Das Problem liegt woanders."},{"option":1,"text":"Von Einzelfällen auf eine allgemeine Wirkung zu schließen, wäre tatsächlich ein Fehler. Die Eltern erzählen aber von keinem Erfolgserlebnis, sie stützen sich allein auf ihr Recht, zu entscheiden. Dieses Recht hat hier die Schwäche."},{"option":3,"text":"Ein Name ersetzt keinen Beleg, das stimmt allgemein. Die Eltern nennen aber niemanden, auf den sie sich stützen; sie berufen sich allein auf ihr eigenes Recht. Ein Autoritätsargument liegt deshalb nicht vor."}],"familie":"berechtigten-kern-anerkennen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Grundgesetz Art. 6 Abs. 2 (Elternrecht und -pflicht, Wächteramt des Staates)","oeffentlich":true,"url":"https://www.gesetze-im-internet.de/gg/art_6.html","abruf":"2026-10-12"},{"typ":"url","kurz":"BGB § 1666 Abs. 1 (Gefährdung des Kindeswohls)","oeffentlich":true,"url":"https://www.gesetze-im-internet.de/bgb/__1666.html","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"46dc26022f22773b"}},{"id":"qx-g-016","clusterId":"G","werkstueckRef":"G.2.1","stufe":1,"question":"In einer Diskussion sagt jemand: „Dass die Wirtschaft so schlecht läuft, liegt an den Eliten. Die steuern im Hintergrund alles, Politik, Konzerne und Medien. Wenn ein Politiker sich als unschuldig erweist, war er eben nur eine Marionette der wahren Elite.“ Was ist an dieser Argumentation das Kernproblem?","options":["Die Behauptung lässt sich nie widerlegen: Die „Eliten“ bleiben undefiniert, und jeder entlastete Politiker gilt als Marionette der wahren Elite.","Die Behauptung ist ein Strohmann: Sie unterstellt Kritikern der Eliten eine Position, die diese nie vertreten haben, und widerlegt nur diese.","Die Behauptung ist ein Mehrheitsargument: Sie gilt schon deshalb als wahr, weil angeblich sehr viele Menschen so denken, und ersetzt damit jeden Beleg.","Die Behauptung ist ein Autoritätsargument: Sie stützt sich auf ungenannte Fachleute, deren angebliches Wissen niemand überprüfen kann."],"correctIndex":0,"explanation":"Das Argument ist durch Vagheit gegen Widerlegung abgeschirmt: Da nie genau definiert wird, wer „die Eliten“ sind, kann die Behauptung nie widerlegt werden. Erweist sich ein Beschuldigter als unschuldig, war er eben nur eine Marionette der „wahren Elite“ dahinter. Der Feind ist wie ein Nebel, man kann ihn nicht festnageln. Wer eine solche Behauptung ernsthaft prüfen will, braucht deshalb Präzision: konkrete Namen und überprüfbare Belege dafür, dass sich diese Personen abgesprochen haben. Außerdem wird aus Menschen in Machtpositionen eine einzige, geheime und bösartige Kabale gemacht. Einen Strohmann baut der Sprecher nicht, denn er widerlegt keine Gegenposition. Auf eine Mehrheit beruft er sich ebenfalls nicht. Und Fachleute führt er nicht ins Feld, das Problem liegt allein in der Struktur der Behauptung.","coreRule":"⚡ Wer „die Eliten“ sagt, ohne Namen und Belege zu nennen, baut eine Behauptung, die sich nicht widerlegen lässt. Frag deshalb nach konkreten Personen und überprüfbaren Absprachen.","beleg":"Werkstück G.2.1 (Die linguistische Autopsie)","status":"entwurf","scenario":"","kurz":"Die Behauptung lässt sich nicht widerlegen, weil unklar bleibt, wer „die Eliten“ sind, und jede Entlastung als Beweis für noch mehr Verschleierung umgedeutet wird. Der Denkfehler: Eine Aussage, die nichts ausschließen kann, sagt auch nichts.","prueffrage":"Was bleibt von der Behauptung übrig, wenn sich ein beschuldigter Politiker als unschuldig erweist?","rueckmeldung":[{"option":1,"text":"Pauschal ist die Behauptung tatsächlich, und Menschen in Machtpositionen werden zu einer einzigen Gruppe zusammengezogen. Ein Strohmann wäre sie aber nur, wenn der Sprecher einer Gegenposition etwas unterstellte und das widerlegte, und das tut er nicht."},{"option":2,"text":"Verschwörungsbehauptungen kommen oft mit dem Anschein breiter Zustimmung daher. Hier aber verweist der Sprecher mit keinem Wort darauf, wie viele Menschen so denken. Das Problem liegt in der Bauweise der Behauptung selbst."},{"option":3,"text":"Belege fehlen in der Tat, und das macht die Behauptung dünn. Ein Autoritätsargument braucht jedoch Fachleute oder Experten, auf die man sich beruft, und der Sprecher nennt keine. Dass seine Behauptung unprüfbar bleibt, hat eine andere Ursache."}],"familie":"kritik-braucht-adresse","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (überarb. 31.07.2026), Abschn. 2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"f91c12607871038c"}},{"id":"qx-g-017","clusterId":"G","werkstueckRef":"G.2.1","stufe":2,"question":"Was ist an dieser Behauptung das zentrale Problem, und welche Rückfrage prüft sie am besten?","scenario":"In einer Diskussion sagt jemand: „Die Eliten haben die Krise geplant.“ Auf Nachfrage, wer das sei, antwortet er: „Na, die da oben eben, die halten alle zusammen.“ Als einzelne Politiker oder Konzernchefs genannt werden, die nachweislich nichts abgesprochen haben, sagt er: „Die waren doch nur Marionetten der wahren Elite dahinter.“","options":["Die Behauptung stützt sich auf eine einzelne persönliche Erfahrung als Beweis (Anekdote). Am besten fragst du, wann der Sprecher selbst erlebt hat, dass Mächtige ihm geschadet haben.","Die Behauptung bleibt unwiderlegbar, weil „die Eliten“ nie festgelegt werden. Am besten fragst du, wer konkret dazugehört und welchen überprüfbaren Beleg es für ihre Absprache gibt.","Die Behauptung stützt sich auf das Wort einer Fachperson (Autoritätsargument). Am besten fragst du, welche Qualifikation diese Fachperson hat und ob sie unabhängig ist.","Die Behauptung beruft sich darauf, dass viele Menschen sie teilen (Mehrheitsargument). Am besten fragst du, wie viele Menschen das tatsächlich glauben und woher die Zahl stammt."],"correctIndex":1,"explanation":"Der Begriff „die Eliten“ wird nie definiert, und jeder Gegenbeweis wird mit „Marionette der wahren Elite“ aufgefangen. Eine Behauptung, die durch keinen denkbaren Fall widerlegt werden kann, sagt nichts Überprüfbares über die Welt. Die Rückfrage nach konkreten Personen, einem konkreten Ziel und einem Beleg für die Absprache macht aus der Stimmung eine prüfbare Aussage. Sie bestreitet nicht, dass es einflussreiche Gruppen gibt oder dass Mächtige kritisiert werden dürfen. Sie zeigt nur, ob die Behauptung etwas Festes enthält, das man testen kann. Eine Einzelerfahrung als Beweis führt der Sprecher nicht an. Auch Fachleute nennt er nicht. Und von einer Mehrheit, die so denkt, ist ebenfalls keine Rede, die Rückfragen danach liefen deshalb ins Leere.","coreRule":"⚡ Wer „die Eliten“ sagt, soll Namen, Ziel und Beleg nennen können. Eine Behauptung, die jeden Gegenbeweis einbaut, ist unprüfbar.","quote":"Kannst du bitte präzise sein? Wer genau gehört zu diesen ‚Eliten‘? Nenne bitte fünf Namen.","quoteLabel":"Merksatz:","beleg":"Werkstück G.2.1 (Das Anti-Denkmuster; Aktivierungs-Frage)","status":"entwurf","kurz":"Die Behauptung ist unwiderlegbar, weil „die Eliten“ nie festgelegt werden und jeder Gegenfall zur Marionette erklärt wird. Erst die Frage nach konkreten Personen und einem Beleg für ihre Absprache macht daraus etwas Prüfbares.","prueffrage":"Was ändert sich an der Behauptung, nachdem Politiker genannt wurden, die nachweislich nichts abgesprochen haben?","rueckmeldung":[{"option":0,"text":"Misstrauen gegenüber Mächtigen speist sich oft aus eigenen Erfahrungen. Hier führt der Sprecher aber gar keine an. Und selbst wenn: Die Frage nach seinem Erleben prüft ihn, nicht die Behauptung."},{"option":2,"text":"Bei einem Expertenzitat wäre die Frage nach Qualifikation und Unabhängigkeit der richtige Hebel. Im Gespräch beruft sich der Sprecher aber auf keine Fachperson, die Rückfrage hätte also nichts, woran sie ansetzen könnte."},{"option":3,"text":"„Die halten alle zusammen“ klingt nach einer breiten Überzeugung. Der Sprecher sagt aber nichts darüber, wie viele das glauben. Die Frage nach der Zahl ginge daher ins Leere und würde die Behauptung selbst nicht prüfen."}],"familie":"kritik-braucht-adresse","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (überarb. 31.07.2026), Abschn. 2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"eb1e71b9d22dd99e"}},{"id":"qx-g-018","clusterId":"G","werkstueckRef":"G.2.1","stufe":3,"question":"Wie solltest du den Beitrag und den Streit der beiden Leser am besten beurteilen?","scenario":"In einem Online-Beitrag wird mehrfach „Globalisten“ als Schuldiger für Wirtschaftskrise, Pandemie und Kriege genannt. Wer damit gemeint ist, bleibt offen, und Juden werden nirgends erwähnt. Eine Leserin schreibt darunter: „Das ist doch klar antisemitisch!“ Ein anderer Leser antwortet: „Das Wort ist völlig neutral, du unterstellst da etwas.“","options":["Das Wort gilt in solchen Zusammenhängen als bekannter antisemitischer Code. Ob es hier so gemeint ist, zeigt erst der Kontext: wer genau gemeint ist und welche Belege es gibt.","Das Wort ist ohne Nennung von Juden nur ein Wort. Da der Text niemanden ausdrücklich meint, darf man ihm keine antisemitische Aussage zuschreiben, solange der Verfasser sie nicht selbst bestätigt.","Das Wort gilt als bekannter antisemitischer Code. Wer mögliche Betroffene schützen will, behandelt den Beitrag deshalb als antisemitisch, bis der Verfasser das Gegenteil belegt.","Das Wort lässt sich nicht eindeutig deuten. Da niemand in den Verfasser hineinsehen kann, ist jede Einordnung des Beitrags Spekulation, und beide Leser liegen gleich weit von der Wahrheit entfernt."],"correctIndex":0,"explanation":"Beide Leser machen denselben Fehler: Sie entscheiden, bevor sie geprüft haben. Das Wort „Globalisten“ ist vage; wer damit gemeint ist, bleibt offen, und gerade diese Vagheit macht es unwiderlegbar und vielseitig einsetzbar. In verschwörungsfantastischen Zusammenhängen wird es in der Fachliteratur (Weiß 2024) als bekannter Code geführt, der an die alte antisemitische Erzählung von einer weltbeherrschenden Finanzmacht anknüpft, ohne Juden zu nennen. Das gibt dem Sprecher plausible Abstreitbarkeit. Chapelan (2024) hält zugleich fest, dass Verschwörungserzählungen ohne jüdischen Bezug nicht per se antisemitisch sind. Aus dem Wort allein folgt also weder ein sicherer Beleg für antisemitische Absicht noch das Gegenteil; man prüft Kontext und Belege. Die gute Prüfung fragt: Wer genau ist gemeint, und welcher Beleg stützt die Schuldzuweisung? Nur den Wortlaut gelten zu lassen, geht am Kern vorbei, denn ein Code lebt gerade davon, dass er nichts ausdrücklich nennt. Das Wort schon als Beweis zu nehmen, wäre ebenso verfrüht, weil Kontext und Belege noch fehlen. Und sich herauszuhalten klärt nichts, denn der Kontext lässt sich ja prüfen.","coreRule":"⚡ Entscheide bei einem vagen Reizwort nicht aus dem Bauch, sondern prüfe den Kontext: Welche Gruppe ist gemeint, welcher Beleg liegt vor, welches Bild steht dahinter?","beleg":"Werkstück G.2.1 (Funktion als Hundepfeife); Fn. gl-g-globalisten (Weiß 2024, S. 172; Chapelan 2024, S. 181)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Das Wort ist als Code bekannt, beweist aber allein noch keine Absicht. Der Fehler beider Leser ist, vor der Prüfung zu urteilen: Kontext und Belege zeigen, wer gemeint ist und was die Schuldzuweisung stützt.","prueffrage":"Welche Angaben über den Verfasser und den Zusammenhang des Beitrags lagen den beiden Lesern vor, als sie urteilten?","rueckmeldung":[{"option":1,"text":"Dass man ohne Beleg nichts unterstellen darf, stimmt. Nur den Wortlaut gelten zu lassen, geht aber am Kern vorbei, denn ein Code lebt davon, dass er nichts ausdrücklich nennt. Der Kontext lässt sich ohne Geständnis prüfen."},{"option":2,"text":"Der Schutzgedanke ist nachvollziehbar, und das Wort gilt tatsächlich als bekannter Code. Als Beweis taugt es allein aber nicht, denn nicht jede Verschwörungserzählung ist antisemitisch. Wer bis zum Gegenbeweis verurteilt, urteilt vor der Prüfung."},{"option":3,"text":"Aus dem Wort allein folgt tatsächlich kein sicheres Urteil. Spekulation ist die Einordnung aber nur, solange man nichts prüft: Wer gemeint ist und welche Belege es gibt, lässt sich klären. Beide Leser urteilen vorschnell."}],"familie":"kritik-braucht-adresse","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Weiß, M. (2024): Impliziter Antisemitismus. In: Schuch, C. (Hg.): Antisemitismus und Recht. Bielefeld: transcript, 159–182 (CC BY 4.0)","oeffentlich":true,"doi":"10.14361/9783839466872-008","seite":"172"},{"typ":"doi","kurz":"Chapelan, A. (2024): Conspiracy Theories. In: Becker, M. J. u. a. (Hg.): Decoding Antisemitism. Cham: Palgrave Macmillan, 175–190 (CC BY 4.0)","oeffentlich":true,"doi":"10.1007/978-3-031-49238-9_13","seite":"181"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"ce0ab7bab297bbb4"}},{"id":"qx-g-019","clusterId":"G","werkstueckRef":"G.2.1","stufe":4,"question":"Du sollst prüfen, ob dieser Beitrag seine Behauptung belegt. Was ist die zentrale Schwäche seiner Argumentation?","scenario":"Ein Beitrag reiht auf: steigende Energiepreise in Land A, ein Handelsabkommen in Land B, der Rücktritt eines Bankers in Land C – „alles Teil des Plans der Globalisten“. Dass die drei Ereignisse etwas miteinander zu tun haben, wird nirgends gezeigt, nur behauptet.","options":["Aus dem bloßen Nebeneinander verschiedener Ereignisse wird ein gemeinsamer Plan abgeleitet, ohne dass eine Verbindung zwischen ihnen belegt wird.","Der Plan wird mit dem Urteil ungenannter Fachleute begründet, das niemand prüfen kann, sodass ein Autoritätsargument die Behauptung trägt.","Der Plan gilt als bewiesen, weil angeblich viele Menschen an ihn glauben, sodass ein Mehrheitsargument an die Stelle eines Belegs tritt.","Der Beitrag widerlegt eine Gegenposition, die niemand vertritt, und tut so, als sei damit der Plan bewiesen; ein Strohmann ersetzt den Beleg."],"correctIndex":0,"explanation":"Die Schwäche liegt im Schluss, nicht in den Einzelereignissen: Energiepreise, Handelsabkommen und Rücktritte können einzeln durchaus stimmen. Scheinbar unzusammenhängende Handlungen werden hier als Beweis für einen koordinierten Plan gedeutet; das Auge sucht eben Muster, auch im Rauschen (Apophenie). Belegt wäre ein Plan nur durch konkrete, überprüfbare Beweise für eine Absprache. Außerdem bleibt der „Plan der Globalisten“ so vage, dass jedes Ereignis nachträglich als Beweis passt und nichts ihn widerlegen könnte (Unfalsifizierbarkeit durch Vagheit). Gleichzeitigkeit ist noch keine Koordination. Der Beitrag nennt keine Fachleute, deshalb liegt kein Autoritätsargument vor. Er beruft sich nicht auf eine Mehrheit, die an den Plan glaubt. Und er widerlegt keine Gegenposition, ein Strohmann kommt nicht vor.","coreRule":"⚡ Gleichzeitigkeit ist keine Koordination: Verlange den Beleg für die Verbindung, nicht nur für die Einzelereignisse.","beleg":"Werkstück G.2.1 (Die rhetorische Funktion: Unfalsifizierbarkeit durch Vagheit; Die transportierten Denkfehler: Apophenie)","status":"entwurf","kurz":"Aus dem bloßen Nebeneinander dreier Ereignisse folgt noch kein gemeinsamer Plan: Gleichzeitigkeit ist keine Koordination. Das Auge sucht Muster, auch im Rauschen. Belegt wäre ein Plan nur durch überprüfbare Hinweise auf eine Absprache.","prueffrage":"Welche Beteiligten haben die drei Ereignisse gemeinsam, und woran ließe sich das nachprüfen?","rueckmeldung":[{"option":1,"text":"Unprüfbare Fachleute wären tatsächlich ein schwaches Fundament. Der Beitrag nennt aber überhaupt keine Fachleute oder Quellen, er reiht nur Ereignisse auf und behauptet den Zusammenhang."},{"option":2,"text":"Ein Plan wird nicht dadurch wahr, dass viele ihn glauben. Das ist aber hier gar nicht der Punkt: Der Beitrag beruft sich auf keine Mehrheit, sondern deutet ein bloßes Nebeneinander als Plan."},{"option":3,"text":"Einen Gegner mit verzerrter Position aufzubauen, ersetzt tatsächlich oft den Beleg. Im Beitrag taucht aber keine Gegenposition auf, die widerlegt würde. Er reiht nur Ereignisse auf und behauptet den Zusammenhang."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"b2a75951f4d42bec"}},{"id":"qx-g-020","clusterId":"G","werkstueckRef":"G.2.2","stufe":1,"question":"Welcher Denkfehler steckt in dieser Aussage, und welche Gegenfrage deckt ihn am besten auf?","options":["Die Aussage fasst sehr unterschiedliche Redaktionen zu einer einzigen Stimme zusammen (Pauschalisierung). Eine gute Gegenfrage lautet: „Welche konkreten Medien meinst du, und widersprechen sie einander wirklich nie?“","Die Aussage verwechselt Ursache und Wirkung (umgekehrte Kausalität). Eine gute Gegenfrage lautet: „Haben die Medien das Misstrauen erzeugt, oder hat das Misstrauen die Medien erzeugt?“","Die Aussage beruft sich auf eine falsche Autorität (Autoritätsargument). Eine gute Gegenfrage lautet: „Welcher Experte hat dir das so bestätigt?“","Die Aussage behauptet eine Kette immer schlimmerer Folgen, die aus einem ersten Schritt zwangsläufig folgen (schiefe Ebene). Eine gute Gegenfrage lautet: „Warum soll aus dem ersten Schritt zwingend der nächste folgen?“"],"correctIndex":0,"explanation":"„Die Medien“ ist ein Sammelbegriff für sehr viele Redaktionen mit unterschiedlichen Eigentümern, Zielgruppen und politischen Ausrichtungen. Wer sie zu einer einzigen, koordinierten Stimme verschmilzt, pauschalisiert und ignoriert Vielfalt und Konkurrenz: Zeitungen wie taz und NZZ oder New York Times und Wall Street Journal vertreten oft gegensätzliche Positionen. Die Gegenfrage zwingt zur Konkretisierung und macht die Behauptung überprüfbar. Dass einzelne Artikel Fehler enthalten können, ist damit nicht bestritten; es ist aber etwas anderes als eine pauschale Gleichschaltung aller Medien. Ein Pauschalurteil lässt sich nicht widerlegen, ein konkreter Fall dagegen schon. Über Ursache und Wirkung von Misstrauen sagt der Verwandte nichts, eine umgekehrte Kausalität liegt nicht vor. Er beruft sich auf keine Autorität. Und eine Kette immer schlimmerer Folgen malt er ebenfalls nicht aus.","coreRule":"⚡ „Die Medien“ gibt es nicht als eine Stimme, sondern als viele, die einander widersprechen.","beleg":"Werkstück G.2.2 (Die rhetorische Funktion, Punkt 3: Schaffung eines Strohmanns)","status":"entwurf","scenario":"Bei einem Familientreffen kommt das Gespräch auf Nachrichten. Ein Verwandter sagt: „Die Medien lügen doch alle dasselbe, die sind gleichgeschaltet.“","kurz":"„Die Medien“ sind viele Redaktionen mit verschiedenen Eigentümern, Zielgruppen und Ausrichtungen, die einander oft widersprechen. Wer sie zu einer Stimme verschmilzt, pauschalisiert. Die Nachfrage nach konkreten Medien macht die Behauptung überprüfbar.","prueffrage":"Nennt der Verwandte für sein Urteil eine Quelle, ein Erlebnis oder eine Ursache, oder nur das Urteil selbst?","rueckmeldung":[{"option":1,"text":"Medien und Misstrauen werden oft gemeinsam genannt, deshalb liegt die Frage nach der Richtung nahe. Der Verwandte behauptet aber keinen solchen Zusammenhang, er hält alle Medien für gleichgeschaltet. Die Gegenfrage geht daher an der Aussage vorbei."},{"option":2,"text":"Bei kühnen Behauptungen fragt man gern reflexhaft nach der Quelle. Hier beruft sich der Verwandte aber auf niemanden, er stellt eine Pauschalbehauptung auf. Die Frage nach dem Experten verlangt nicht, dass er sie konkretisiert."},{"option":3,"text":"„Gleichgeschaltet“ klingt nach einer dramatischen Entwicklung. Beschrieben wird aber nur ein Zustand, es wird keine Kette immer schlimmerer Folgen aus einem ersten Schritt ausgemalt. Die Gegenfrage nach dem zwingenden nächsten Schritt hat deshalb nichts, woran sie ansetzen kann."}],"familie":"kritik-braucht-adresse","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Sprachkritische Aktion Unwort des Jahres (13.01.2015): Pressemitteilung „Unwort des Jahres 2014: Lügenpresse“","oeffentlich":true,"url":"https://www.unwortdesjahres.net/wp-content/uploads/2021/06/pressemitteilung_unwort2014.pdf","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"6fe0adde35c26853"}},{"id":"qx-g-021","clusterId":"G","werkstueckRef":"G.2.2","stufe":2,"question":"Welcher Denkfehler steckt in der Art, wie dein Onkel Meldungen bewertet?","scenario":"Dein Onkel sagt über Zeitungen und Fernsehsender: „Das stand in der Zeitung, also gelogen.“ Eine Meldung, die sein Weltbild stützt, lässt er dagegen als „seltene Ausnahme von gutem Journalismus“ gelten. Meldungen, die ihm widersprechen, wertet er als weiteren Beweis dafür, dass „die Lügenpresse“ eben lügt.","options":["Er hält Meldungen nur für wahr oder gelogen und lässt keinen Raum für Irrtümer, Fehler und Zwischenstufen.","Er schließt von einer einzelnen Falschmeldung auf alle Meldungen derselben Zeitung und prüft die übrigen nicht einzeln.","Er macht die Zeitungen zur einzigen Ursache aller gesellschaftlichen Probleme und übersieht andere Einflüsse.","Er wertet Meldungen danach, ob sie zu seinem Weltbild passen, nicht nach ihrem Inhalt."],"correctIndex":3,"explanation":"Der Onkel bewertet nicht den Inhalt einer Meldung, sondern nur, ob sie zu seinem Weltbild passt. Passende Meldungen gelten selbst dann als glaubwürdig, wenn sie aus derselben Quelle stammen, nur als „seltene Ausnahme“. Widersprechende Meldungen zählen als zusätzlicher Beweis für seine Sicht. So bestätigt jede Nachricht sein Weltbild, und keine kann es mehr korrigieren. Das ist ein Bestätigungsfehler. Ein pauschales Etikett wie „Lügenpresse“ verstärkt ihn, weil es als Filter wirkt: Es macht die Prüfung des einzelnen Artikels überflüssig. Dass er die Zeitungen als Ganzes verwirft, statt Meldungen zu prüfen, erinnert zwar an ein Ad hominem. Der Kern seines Fehlers ist aber, dass er je nach Weltbild unterschiedlich misst. Auch ein Monokausaler Fehlschluss liegt nicht vor, denn der Onkel benennt in seinen Sätzen keine Ursachen für gesellschaftliche Probleme. Sinnvoll ist es, auf Spezifität zu bestehen: Welcher Artikel enthält welche überprüfbare Falschaussage, und wurde sie später korrigiert?","coreRule":"⚡ Wenn jede Nachricht danach gewertet wird, ob sie ins Weltbild passt, ist das keine Prüfung, sondern ein Filter.","beleg":"Werkstück G.2.2 (Die transportierten Denkfehler: Bestätigungsfehler)","status":"entwurf","kurz":"Der Onkel bewertet nicht den Inhalt einer Meldung, sondern ob sie zu seinem Weltbild passt. Deshalb bestätigt jede Nachricht seine Sicht und keine kann sie korrigieren. Das ist ein Bestätigungsfehler, den ein Etikett wie „Lügenpresse“ noch verstärkt.","prueffrage":"Was haben die Meldungen gemeinsam, die der Onkel gelten lässt, und aus welchen Quellen stammen sie?","rueckmeldung":[{"option":0,"text":"Dass er nur „wahr“ oder „gelogen“ kennt, zeigt sich in seinen Sätzen tatsächlich. Sein Maßstab wechselt aber je nach Weltbild: Passende Meldungen gelten als gut, andere als Lüge. Das Problem ist die ungleiche Messung, nicht die grobe Einteilung."},{"option":1,"text":"Einzeln prüft er tatsächlich nicht. Von einer einzelnen Falschmeldung, von der er verallgemeinert, ist aber nirgends die Rede, und passende Meldungen derselben Quellen lässt er sogar gelten: Er misst je nach Weltbild unterschiedlich."},{"option":2,"text":"Von gesellschaftlichen Problemen und ihren Ursachen spricht der Onkel gar nicht; es geht allein darum, wie er Meldungen bewertet. Eine Alleinursache für irgendetwas benennt er nirgends."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://climatecommunication.gmu.edu/wp-content/uploads/2023/09/ConspiracyTheoryHandbook.pdf","seite":"7","abruf":"2026-10-12"},{"typ":"doi","kurz":"Nickerson, R. S. (1998): Confirmation Bias: A Ubiquitous Phenomenon in Many Guises. Review of General Psychology 2(2), 175–220","oeffentlich":false,"doi":"10.1037/1089-2680.2.2.175"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"eac9127cbbfc399e"}},{"id":"qx-g-022","clusterId":"G","werkstueckRef":"G.2.2","stufe":3,"question":"Ein Bekannter sagt, ein Pauschalvorwurf wie „Lügenpresse“ sei doch bloß ein derber Ausdruck für Medienkritik und deshalb unproblematisch. Was ist die stärkste Gegenüberstellung?","options":["Der Ausdruck verwirft alle Medien pauschal, statt einen konkreten Fehler zu benennen, und er war schon im Ersten Weltkrieg ein nationalistischer Kampfbegriff.","Der Ausdruck wird allein damit gerechtfertigt, dass ihn viele Menschen benutzen, doch Verbreitung ersetzt weder einen Beleg noch eine sachliche Kritik.","Der Ausdruck wird mit dem Verweis auf andere Berufsgruppen verteidigt, die man ebenfalls hart kritisiert, und lenkt so von der Sache ab (Whataboutism).","Der Ausdruck wird mit dem Namen einer Autorität gerechtfertigt, die ihn gebilligt haben soll, doch ein Name allein ersetzt keinen Beleg."],"correctIndex":0,"explanation":"Berechtigte Medienkritik benennt einen konkreten Artikel, einen überprüfbaren Fehler und fragt, ob er korrigiert wurde. Ein Pauschalbegriff wie „Lügenpresse“ leistet das nicht: Er verwirft alle Quellen auf einmal und macht jede Gegeninformation von vornherein verdächtig. Dazu kommt die Herkunft des Wortes. Es ist älter als der Nationalsozialismus und war spätestens im Ersten Weltkrieg ein nationalistischer Kampfbegriff gegen die Presse. Die NS-Propaganda griff ihn auf und spitzte ihn antisemitisch zu, etwa gegen eine „jüdisch marxistische Lügenpresse“. Nach 1945 verschwand er weitgehend und wurde ab Oktober 2014 im Umfeld von Pegida wiederbelebt. Die Jury der Aktion „Unwort des Jahres“ wählte ihn im Januar 2015 zum Unwort des Jahres 2014, weil er Medien pauschal diffamiere und die für die Demokratie nötige Pressefreiheit gefährde, und verwies dabei ausdrücklich auf die NS-Vorgeschichte. Der Einwand „Das hat mit früher nichts zu tun“ ist also sachlich falsch. Das Problem liegt in der Generalanklage statt in der Kritik an konkreten Fehlern. Der Bekannte begründet den Ausdruck nicht mit seiner Verbreitung. Er weicht auch nicht auf andere Berufsgruppen aus, ein Whataboutism liegt also nicht vor. Und eine Autorität führt er ebenfalls nicht an.","coreRule":"⚡ Ein Kampfbegriff hat eine Geschichte: Wer ihn benutzt, ruft sie mit auf.","beleg":"Werkstück G.2.2 (Historische Anknüpfung); Fn. gl-g-1 (Unwort des Jahres 2014, Jury-Begründung vom 13.01.2015; Begriffsgeschichte: Schmitz-Berning 2007, S. 327)","status":"entwurf","scenario":"Beim Abendessen verteidigt ein Bekannter den Ausdruck „Lügenpresse“: „Das ist halt zugespitzte Kritik. Wer Medien kritisiert, muss auch mal deutlich werden dürfen. Das hat doch mit früher nichts zu tun.“","kurz":"„Lügenpresse“ verwirft alle Medien auf einmal, statt einen überprüfbaren Fehler zu benennen. Dazu kommt die Herkunft: Das Wort war schon im Ersten Weltkrieg ein nationalistischer Kampfbegriff. Es mit „früher hat damit nichts zu tun“ abzutun, geht daher fehl.","prueffrage":"Seit wann ist „Lügenpresse“ als Schlagwort belegt, und wer hat es damals gegen wen benutzt?","rueckmeldung":[{"option":1,"text":"Dass Verbreitung keinen Beleg ersetzt, stimmt. Der Bekannte stützt sich aber gar nicht darauf, dass viele den Ausdruck benutzen. Sein Argument ist „zugespitzte Kritik“, und genau dort liegt das Problem."},{"option":2,"text":"Mit Whataboutism hat die Äußerung nichts zu tun: Der Bekannte zieht keine anderen Berufsgruppen heran, sondern rechtfertigt den Ausdruck direkt als deutliche Kritik. Die Schwäche liegt darin, dass der Pauschalbegriff gar keinen konkreten Fehler benennt."},{"option":3,"text":"Eine Autorität kommt im Gespräch nicht vor, der Bekannte beruft sich auf niemanden, der den Ausdruck gebilligt haben soll. Wer das hineinliest, geht an dem vorbei, was gesagt wurde. Offen bleibt die Frage, ob „Lügenpresse“ überhaupt konkrete Kritik leistet."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Sprachkritische Aktion Unwort des Jahres (13.01.2015): Pressemitteilung „Unwort des Jahres 2014: Lügenpresse“","oeffentlich":true,"url":"https://www.unwortdesjahres.net/wp-content/uploads/2021/06/pressemitteilung_unwort2014.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Schmitz-Berning, C. (2007): Vokabular des Nationalsozialismus. 2. Aufl. Berlin, New York: de Gruyter, s. v. „Journaille“","oeffentlich":false,"seite":"327"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"2beef17f8800a0c2"}},{"id":"qx-g-023","clusterId":"G","werkstueckRef":"G.2.2","stufe":4,"question":"Du sollst einschätzen, ob die Antwort des Sprechers berechtigte Medienkritik oder pauschale Delegitimierung ist. Welche Prüfung führt am besten zu einem begründeten Urteil?","scenario":"Nach einem Produktrückruf berichten mehrere Zeitungen kritisch über ein Unternehmen. Dessen Sprecher erklärt: „Das ist alles gekaufte Hetzpresse, da ist kein Wort wahr.“ Ein Artikel nennt einen konkreten Mangel mit Chargennummer, ein anderer enthält eine Zahl, die das Unternehmen für falsch hält.","options":["Man prüft, welche redaktionelle Linie die Zeitungen haben, denn Häuser mit klarer Linie gewichten Themen oft einseitig.","Man prüft den Ruf der Zeitungen, denn etablierte und angesehene Häuser machen seltener Fehler als unbekannte.","Man prüft, ob ein konkreter Artikel mit überprüfbarer Falschaussage benannt wird und ob die Redaktion diese später korrigierte.","Man prüft, wie emotional die Berichte formuliert sind, denn zugespitzte Sprache deutet oft auf Meinungsmache statt auf Information."],"correctIndex":2,"explanation":"Berechtigte Kritik hat eine Adresse: Welcher Artikel, wann, welche überprüfbare Falschaussage, und wurde sie korrigiert? Das lässt sich nachprüfen und im Zweifel widerlegen. Der Pauschalvorwurf „gekaufte Hetzpresse“ verwirft dagegen eine ganze Quelle wegen ihrer angeblichen Zugehörigkeit statt den einzelnen Beitrag zu prüfen, ein Ad Hominem. Jede Kritik, die von dort kommt, lässt sich dann als Bestätigung des eigenen Weltbildes abtun. Journalistische Fehler und Tendenzen zu leugnen wäre ebenso falsch; entscheidend ist die Spezifität. Die redaktionelle Linie einer Zeitung sagt nur, wie sie Themen gewichtet, nicht ob ein einzelner Satz stimmt. Auch ein guter Ruf schützt nicht vor einem Fehler im konkreten Fall. Und ein emotionaler Ton macht eine Aussage weder wahr noch falsch; dafür braucht es den konkreten Beleg.","coreRule":"⚡ Kritik an Medien hat eine Adresse: Artikel, Datum, Aussage, Korrektur.","beleg":"Werkstück G.2.2 (Das Anti-Denkmuster; Ad Hominem)","status":"entwurf","kurz":"Berechtigte Kritik hat eine Adresse: ein benannter Artikel mit einer überprüfbaren Falschaussage und die Frage, ob korrigiert wurde. „Gekaufte Hetzpresse“ verwirft dagegen ganze Quellen pauschal, statt einen einzelnen Beitrag zu prüfen.","prueffrage":"Wie lautet die Zahl, die das Unternehmen für falsch hält, und welche Zahl nennt es selbst?","rueckmeldung":[{"option":0,"text":"Redaktionelle Linien gewichten Themen tatsächlich unterschiedlich. Ob die Chargennummer oder die strittige Zahl stimmt, sagt die Linie aber nicht; das lässt sich nur am einzelnen Beitrag klären."},{"option":1,"text":"Ein guter Ruf ist ein Hinweis, aber kein Beleg für den Einzelfall, denn auch angesehene Häuser machen Fehler. Geprüft würde so die Zeitung als Ganzes, nicht die strittige Aussage."},{"option":3,"text":"Zugespitzte Sprache kann auf Meinungsmache hindeuten. Wahr oder falsch ist eine Aussage aber unabhängig vom Ton: Auch ein emotionaler Bericht kann stimmen, ein nüchterner falsch sein."}],"familie":"kritik-braucht-adresse","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Deutscher Presserat: Pressekodex (Fassung 19.03.2025), Ziffer 3 Richtigstellung","oeffentlich":true,"url":"https://www.presserat.de/pressekodex.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Sprachkritische Aktion Unwort des Jahres (13.01.2015): Pressemitteilung „Unwort des Jahres 2014: Lügenpresse“","oeffentlich":true,"url":"https://www.unwortdesjahres.net/wp-content/uploads/2021/06/pressemitteilung_unwort2014.pdf","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"877c36ae3ea5a3cd"}},{"id":"qx-g-024","clusterId":"G","werkstueckRef":"G.2.3","stufe":1,"question":"Du liest in einem Forum: „Meine Heilpraktikerin sagt, die Schulmedizin behandelt nur Symptome, wir setzen auf ganzheitliche Heilung.“ Du fragst dich, ob das Wort „Schulmedizin“ hier neutral beschreibt oder etwas anderes tut. Woran erkennst du am besten, dass es hier als Kampfbegriff eingesetzt wird?","options":["Das Wort wird abwertend gebraucht und stellt die Medizin als starres System dar, damit die eigene Methode als überlegene Alternative erscheint.","Das Wort schwächt etwas Unangenehmes durch einen milden Ausdruck ab, damit die Sache harmloser klingt, als sie ist (Euphemismus).","Das Wort wirkt als Hochwertwort, das ein Lager mit positiven Gefühlen verbindet, damit die Sprecherin Zustimmung für die eigene Seite gewinnt.","Das Wort dient als Code, den nur Eingeweihte deuten, damit die Sprecherin ihre eigentliche Absicht vor anderen verbergen kann."],"correctIndex":0,"explanation":"Überprüfe, wie das Wort gebraucht wird, nicht das Wort selbst: Wer „Schulmedizin“ abwertend verwendet (hier: „behandelt nur Symptome“) und die wissenschaftsbasierte Medizin als starres System darstellt, um die eigene Methode als überlegene Alternative zu positionieren, nutzt das Wort als Kampfbegriff. Dass das Wort allgemein gebräuchlich ist und sogar in Versicherungsbedingungen vorkommt, zeigt nur, dass es auch neutral verwendet werden kann. Darauf kommt es an: Wer spricht mit welcher Absicht, und was soll durch den Kontrast erreicht werden? Beschönigt wird hier nichts, ein Euphemismus liegt also nicht vor. Das Wort dient auch nicht dazu, die eigene Seite aufzuwerten, denn es wertet die andere ab. Und die Sprecherin verbirgt ihre Absicht nicht hinter einem Code, sondern sagt offen, was sie von der Medizin hält.","coreRule":"⚡ Entscheidend ist nicht das Wort, sondern wer es mit welcher Absicht abwertend einsetzt.","beleg":"Werkstück G.2.3 (Die rhetorische Funktion, Einleitung und Punkt 3: Implizite Abwertung; Abschluss-Diagnose des Pathologen)","status":"entwurf","scenario":"Das Wort „Schulmedizin“ ist im Deutschen allgemein gebräuchlich, es steht sogar in den Musterbedingungen privater Krankenversicherungen.","kurz":"Entscheidend ist, wie das Wort gebraucht wird: Hier wertet es die Medizin als starres System ab, damit die eigene Methode überlegen wirkt. Dass das Wort auch neutral vorkommt, entlastet diesen Gebrauch nicht.","prueffrage":"Welche Eigenschaften schreibt der Forumsbeitrag jeder der beiden Behandlungsarten zu?","rueckmeldung":[{"option":1,"text":"Ein Euphemismus macht etwas Unangenehmes milder. Hier passiert das Gegenteil: „behandelt nur Symptome“ wertet die Medizin ab, statt etwas zu beschönigen."},{"option":2,"text":"Die Sprecherin will tatsächlich Zustimmung für ihre Seite gewinnen. Das geschieht aber nicht durch Aufwertung mit diesem Wort, sondern dadurch, dass „Schulmedizin“ die Gegenseite abwertet und so den Kontrast zur eigenen Methode erzeugt."},{"option":3,"text":"Wörter können Zugehörigkeit signalisieren, und das macht Codes plausibel. Hier ist aber nichts verschlüsselt: Jeder versteht den Satz, und die Sprecherin sagt offen, was sie von der Medizin hält."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Haufe: Schulmedizinklausel § 4 Abs. 6 MB/KK 94 ist wirksam (Kommentar)","oeffentlich":true,"url":"https://www.haufe.de/id/kommentar/schulmedizinklausel-4-abs-6-mbkk-94-ist-wirksam-HI947826.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Wuliger, M. (13.03.2017): Schulmedizin und arische Physik. Jüdische Allgemeine (Kolumne)","oeffentlich":true,"url":"https://www.juedische-allgemeine.de/kultur/schulmedizin-und-arische-physik/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Heissmann, N.; Weymayr, C. (2012): Die Homöopathie-Lüge, Teil 5","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"9371a633f00776a1"}},{"id":"qx-g-025","clusterId":"G","werkstueckRef":"G.2.3","stufe":2,"question":"Welche Antwort entkräftet die Behauptung am besten?","scenario":"Eine Bekannte sagt: „Die Schulmedizin hat seit hundert Jahren nichts dazugelernt, ich bleibe bei sanften Alternativen.“ Du möchtest ihr sachlich antworten, ohne sie bloßzustellen.","options":["Die Medizin ist streng reguliert: Medikamente müssen vor der Zulassung geprüft werden, und Behörden überwachen die Sicherheit der Behandlungen.","Die Medizin prüft ihre Annahmen systematisch und ändert sie, wenn Studien dagegensprechen: Theorien werden verworfen, Behandlungen verbessert.","Die Medizin kann nicht jede Krankheit heilen, aber das können sanfte Alternativen ebenso wenig; auch sie stoßen bei vielen Leiden an Grenzen.","Die Medizin ist ein Beruf mit großer Verantwortung: Ärztinnen und Ärzte durchlaufen ein langes Studium und haften für ihre Behandlungen."],"correctIndex":1,"explanation":"Die Behauptung „hat nichts dazugelernt“ ist eine Tatsachenbehauptung und lässt sich prüfen: Medizinische Lehrmeinungen werden regelmäßig revidiert, wenn bessere Studien vorliegen, und Behandlungen werden laufend verbessert. Das Wort „Schule“ weckt zwar das Bild von Auswendiglernen und Dogma, beschreibt aber eine Medizin, die es so nicht gibt, ein klassischer Strohmann. Eine gute Entgegnung widerlegt den Stillstandsvorwurf mit dem, was die Sache tatsächlich auszeichnet: systematische Selbstkorrektur. Strenge Zulassungsregeln sind richtig, sagen aber nichts darüber, ob die Medizin dazulernt. Der Hinweis auf die Grenzen der Alternativen mag stimmen, widerlegt den Stillstandsvorwurf aber nicht, sondern weicht ihm aus. Und eine lange Ausbildung belegt Sorgfalt, nicht Lernfähigkeit.","coreRule":"⚡ Prüfe, ob das Wort ein Bild erzeugt, das nicht zur Sache passt: „Schule“ suggeriert Stillstand, doch die Medizin korrigiert sich ständig selbst.","beleg":"Werkstück G.2.3 (Die rhetorische Funktion, Punkt 1: Schaffung eines Strohmanns)","status":"entwurf","kurz":"Der Vorwurf „nichts dazugelernt“ lässt sich prüfen, und dagegen spricht die systematische Selbstkorrektur: Lehrmeinungen werden verworfen, wenn bessere Studien vorliegen. „Schule“ weckt das Bild von Dogma, das auf die Medizin nicht passt.","prueffrage":"Welche Behandlung von vor hundert Jahren wird heute noch genauso angewendet, und welche nicht mehr?","rueckmeldung":[{"option":0,"text":"Zulassungsprüfung und Überwachung gibt es tatsächlich, und sie sind wichtig. Sie beantworten aber eine andere Frage, nämlich die nach der Sicherheit, nicht die, ob die Medizin sich weiterentwickelt."},{"option":2,"text":"Dass auch Alternativen an Grenzen stoßen, mag stimmen. Der Vorwurf des Stillstands bleibt dadurch aber unbeantwortet, und das Gespräch könnte schnell zu einem Vergleich der Lager werden."},{"option":3,"text":"Ausbildung und Haftung zeigen, dass der Beruf ernst genommen wird. Ob die Medizin als Ganzes dazulernt, sagen sie jedoch nicht, denn eine gründliche Ausbildung kann auch veraltetes Wissen vermitteln."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Prasad, V. u. a. (2013): A decade of reversal: an analysis of 146 contradicted medical practices. Mayo Clin Proc 88(8), 790–798 (Abstract auf PubMed)","oeffentlich":true,"doi":"10.1016/j.mayocp.2013.05.012","url":"https://pubmed.ncbi.nlm.nih.gov/23871230/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"661249683beb59a0"}},{"id":"qx-g-026","clusterId":"G","werkstueckRef":"G.2.3","stufe":4,"question":"Was ist an dieser Rahmung der Debatte problematisch?","scenario":"Eine Zeitung kündigt eine Debatte an: „Schulmedizin gegen Alternativmedizin“ – zwei Gäste, je fünf Minuten Redezeit, kein Hinweis darauf, was Studien zur Wirksamkeit der jeweiligen Methoden zeigen.","options":["Sie benachteiligt eine Seite, denn die Zeitung verteilt die Redezeit ungleich, sodass ein Gast deutlich länger sprechen darf.","Sie betreibt Rosinenpicken, denn die Zeitung zeigt nur Studien, die eine Seite stützen, und lässt andere weg.","Sie setzt auf ein Autoritätsargument, denn die Gäste gelten allein wegen ihrer Titel als glaubwürdig, obwohl Titel allein nichts belegen.","Sie erzeugt eine falsche Ausgewogenheit, denn der Unterschied zwischen nachgewiesener und fehlender Wirksamkeit verschwindet."],"correctIndex":3,"explanation":"Die Gegenüberstellung zweier Gäste mit gleicher Redezeit suggeriert zwei gleichwertige, konkurrierende Schulen oder Philosophien. Das ist falsche Ausgewogenheit: Gleich viel Raum täuscht gleich viel Beleg vor. In der Realität gibt es Methoden, die ihre Wirksamkeit nach wissenschaftlichen Standards nachgewiesen haben, und Methoden, bei denen das nicht gelungen ist. Das ist ein Unterschied in der Beweislage, keine Frage der Weltanschauung. Auch das Wort „Schulmedizin“ in dieser Gegenüberstellung hilft nicht, denn es macht aus wissenschaftsbasierter Medizin eine bloße Denkschule unter mehreren. Falsch ist die Rahmung „zwei gleichwertige Seiten“, nicht das Thema. Die Redezeit ist mit je fünf Minuten gleich verteilt, eine Benachteiligung liegt also nicht vor. Studien werden gar nicht gezeigt, also kann auch keine Auswahl davon einseitig sein. Und von Titeln oder Ämtern der Gäste ist keine Rede, ein Autoritätsargument spielt also keine Rolle.","coreRule":"⚡ Zwei Gäste sind noch keine zwei gleichwertigen Positionen: Frag nach der Evidenz hinter jeder Seite.","beleg":"Werkstück G.2.3 (Die rhetorische Funktion, Punkt 2: Etablierung einer falschen Symmetrie)","status":"entwurf","kurz":"Zwei Gäste mit gleicher Redezeit lassen zwei gleichwertige Lager erscheinen, obwohl sich die Beleglage unterscheidet: Bei der einen Seite ist Wirksamkeit nachgewiesen, bei der anderen nicht. Gleich viel Raum täuscht gleich viel Beleg vor.","prueffrage":"Welche Gründe nennt die Ankündigung dafür, gerade diese beiden Seiten mit gleicher Redezeit gegenüberzustellen?","rueckmeldung":[{"option":0,"text":"Auf Fairness bei der Redezeit zu achten, ist sinnvoll. Hier ist sie aber gleich verteilt: Beide Gäste bekommen je fünf Minuten. Gerade diese Gleichheit lässt die Seiten gleichwertig wirken, obwohl ihre Beleglage verschieden ist."},{"option":1,"text":"Fehlende Belege fallen tatsächlich auf. Rosinenpicken setzt aber eine Auswahl voraus, und hier werden gar keine Studien gezeigt. Das Problem ist nicht eine einseitige Auswahl, sondern dass die Ankündigung die Beleglage gar nicht erwähnt."},{"option":2,"text":"Titel allein belegen tatsächlich nichts. In der Ankündigung ist aber von Titeln oder Ämtern der Gäste keine Rede. Der Fehler liegt in der Rahmung als Duell zweier gleichwertiger Seiten, nicht in der Autorität der Sprechenden."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Koehler, D. J. (2016): Can journalistic “false balance” distort public perception of consensus in expert opinion? J Exp Psychol Appl 22(1), 24–38 (Abstract auf PubMed)","oeffentlich":true,"doi":"10.1037/xap0000073","url":"https://pubmed.ncbi.nlm.nih.gov/26752513/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"7b68544af04c52ba"}},{"id":"qx-g-027","clusterId":"G","werkstueckRef":"G.2.4","stufe":1,"question":"Welche Antwort prüft die Behauptung am besten, ohne berechtigte Kritik an Konzernen wegzuwischen?","options":["Du fragst nach, welches Unternehmen oder welche Praktik konkret gemeint ist, und ob sich daraus auf alle Ärzte schließen lässt.","Du führst einen dokumentierten Fall von Industrieeinfluss an, der zeigt, dass der wahre Kern der Kritik berechtigt ist.","Du weist darauf hin, dass viele Medikamente nachweislich wirken, und fragst, ob die Person deshalb auf wirksame Behandlungen verzichten will.","Du fragst, welche persönliche Erfahrung mit einem Arzt hinter dem Misstrauen steckt, und gehst auf diese Erfahrung ein."],"correctIndex":0,"explanation":"Misstrauen gegenüber großen, mächtigen Konzernen ist eine gesunde demokratische Haltung, denn die Pharmaindustrie ist ein profitorientiertes System mit nachgewiesenen Fehlverhaltensweisen. Der Denkfehler liegt erst in der pauschalen Verallgemeinerung: Aus berechtigter Kritik an einzelnen Missständen wird die Ablehnung der gesamten wissenschaftsbasierten Medizin und der individuellen Integrität vieler Ärzte und Forscher. Die Rückfrage nach dem konkreten Unternehmen oder Missstand erkennt den wahren Kern an und macht zugleich sichtbar, ob sich die Aussage überhaupt belegen lässt. Der Hinweis auf wirksame Medikamente stimmt, beantwortet aber nicht, ob die Pauschalaussage zutrifft, und geht über die Kritik hinweg. Ein dokumentierter Fall von Industrieeinfluss bestätigt den wahren Kern, prüft aber nicht den Schluss auf alle Ärzte. Die Frage nach der persönlichen Erfahrung ist einfühlsam, lässt die Behauptung selbst aber ungeprüft.","coreRule":"⚡ Misstrauen ist ein Werkzeug, es braucht aber eine Adresse, sonst wird es zum Pauschalurteil.","beleg":"Werkstück G.2.4 (Das Adaptive Talent; Der Kipppunkt; Kontext & Tiefe)","status":"entwurf","scenario":"In einer Diskussion sagt jemand: „Ich traue keinem Arzt mehr, die sind doch alle von Big Pharma gekauft.“ Du willst weder so tun, als gäbe es keine Interessenkonflikte in der Industrie, noch die Pauschalaussage einfach stehen lassen.","quote":"","quoteLabel":"","kurz":"Die Rückfrage nach dem konkreten Unternehmen oder Missstand nimmt den berechtigten Kern der Kritik ernst und zeigt zugleich, ob sich die Aussage belegen lässt. Der Denkfehler liegt erst darin, aus einzelnen Missständen auf alle Ärzte zu schließen.","prueffrage":"Wie viele Ärzte kennt die Person persönlich, und von wie vielen weiß sie, dass sie Geld von Herstellern bekommen?","rueckmeldung":[{"option":1,"text":"Ein dokumentierter Fall zeigt, dass Kritik an der Industrie berechtigt sein kann. Er belegt aber nur diesen Einzelfall und prüft nicht, ob sich daraus auf alle Ärzte schließen lässt."},{"option":2,"text":"Dass viele Medikamente nachweislich wirken, stimmt. Das beantwortet aber nicht, ob die Pauschalaussage zutrifft, und es übergeht die berechtigte Kritik an Interessenkonflikten, statt sie ernst zu nehmen."},{"option":3,"text":"Die Frage nach der persönlichen Erfahrung ist einfühlsam und kann den Anlass des Misstrauens klären. Ob die Behauptung über alle Ärzte stimmt, bleibt dabei aber ungeprüft."}],"familie":"kritik-braucht-adresse","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Krumholz, H. M. u. a. (2007): What have we learnt from Vioxx? BMJ 334, 120–123","oeffentlich":true,"doi":"10.1136/bmj.39024.487720.68","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1779871/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Lundh, A. u. a. (2017): Industry sponsorship and research outcome. Cochrane Database of Systematic Reviews, MR000033","oeffentlich":true,"doi":"10.1002/14651858.MR000033.pub3","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8132492/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"9b92ef69635bd563"}},{"id":"qx-g-028","clusterId":"G","werkstueckRef":"G.2.4","stufe":2,"question":"Welche Antwort nimmt die Sorge ernst und regt zugleich zur Differenzierung an?","scenario":"Jemand sagt: „Ich traue keinem Arzt mehr, die sind doch alle von Big Pharma gekauft.“ Du möchtest das Gespräch offen halten.","options":["„Das klingt nach einer schlechten Erfahrung. Magst du erzählen, was dir mit einem Arzt passiert ist, das dein Vertrauen erschüttert hat?“","„Neue Medikamente werden von unabhängigen Behörden geprüft. Wusstest du, wie streng diese Zulassung in Wirklichkeit abläuft?“","„Industrieeinfluss gibt es, dafür gibt es dokumentierte Fälle. Sind wirklich alle gekauft, oder meinst du bestimmte Praktiken?“","„Wem man vertraut, ist letztlich Ansichtssache. Sollen wir das Thema einfach stehen lassen, bevor wir uns streiten?“"],"correctIndex":2,"explanation":"Der Vorwurf enthält einen wahren Kern: Die Pharmaindustrie ist ein profitorientiertes System mit nachgewiesenen Fehlverhaltensweisen (ein gut dokumentiertes Beispiel ist der Vioxx-Skandal). Hilfreich ist, den berechtigten Teil anzuerkennen und dann zu fragen, ob der Vorwurf für Millionen einzelner Ärzte und Forscher gilt oder für bestimmte, benennbare Praktiken. So wird aus dem Pauschalurteil eine prüfbare Behauptung. Zuzuhören und nach Erfahrungen zu fragen ist freundlich, lässt die Verallgemeinerung aber unberührt. Der Hinweis auf die Zulassungsprüfung stimmt, wehrt die Sorge aber ab, statt sie aufzugreifen. Die Haltung, Vertrauen sei Ansichtssache, beendet das Gespräch, statt die Behauptung prüfbar zu machen.","coreRule":"⚡ Nimm das Misstrauen ernst und frag nach dem Unterschied zwischen einzelnen Praktiken und Millionen von Menschen.","beleg":"Werkstück G.2.4 (Werkbank-Frage; Kontext & Tiefe)","status":"entwurf","kurz":"Der Vorwurf hat einen wahren Kern: Es gibt dokumentierte Fälle von Industrieeinfluss. Die Rückfrage, ob wirklich alle gemeint sind oder bestimmte Praktiken, macht aus dem Pauschalurteil eine prüfbare Behauptung und hält das Gespräch offen.","prueffrage":"Wie reagiert jemand mit dieser Sorge vermutlich, wenn man ihm sagt, es gebe keinen Grund zum Zweifel?","rueckmeldung":[{"option":0,"text":"Nach der Erfahrung zu fragen ist freundlich und zeigt echtes Interesse. Die Verallgemeinerung „alle sind gekauft“ bleibt dabei aber unberührt und wird nicht prüfbar, das Gespräch kommt also kaum zur Differenzierung."},{"option":1,"text":"Dass unabhängige Behörden Medikamente prüfen, stimmt. Der Satz weist die Sorge aber ab, statt sie aufzugreifen, und lässt offen, was am Vorwurf berechtigt ist. Das Gegenüber fühlt sich eher belehrt als verstanden."},{"option":3,"text":"Mit dem Ausweichen vor Streit bleibt das Gespräch zwar ruhig, aber es endet. Vertrauen lässt sich begründen und überprüfen, es ist mehr als bloße Ansichtssache, und die Pauschalaussage bleibt unangetastet."}],"familie":"berechtigten-kern-anerkennen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Krumholz, H. M. u. a. (2007): What have we learnt from Vioxx? BMJ 334, 120–123","oeffentlich":true,"doi":"10.1136/bmj.39024.487720.68","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1779871/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"3ddb57f96a111aec"}},{"id":"qx-g-029","clusterId":"G","werkstueckRef":"G.2.4","stufe":3,"question":"Was ist an dieser Reaktion problematisch?","scenario":"Eine Studie zu einem neuen Medikament wurde vom Hersteller finanziert. Ein Bekannter sagt: „Industriestudie – kann man vergessen.“","options":["Er stützt sich auf das Urteil einer Autorität statt auf Belege (Autoritätsargument), ohne dessen Gründe zu kennen.","Er beruft sich darauf, dass die Mehrheit so urteilt (Bandwagon-Argument), obwohl Mehrheiten nichts beweisen.","Er verzerrt die Aussage der Studie und widerlegt dann die verzerrte Fassung (Strohmann-Argument).","Er verwirft die Studie allein wegen der Finanzierung, ohne Methodik und Ergebnisse geprüft zu haben."],"correctIndex":3,"explanation":"Eine Finanzierung durch den Hersteller ist ein berechtigter Anlass, genauer hinzusehen: Wer von einem Ergebnis profitiert, hat einen Anreiz zur Schönfärberei. Die Herkunft des Geldes sagt aber noch nichts darüber, ob die Studie sauber gemacht wurde; das zeigt sich erst an Methodik und Ergebnissen. Wer jede industriefinanzierte Studie automatisch für ungültig erklärt, verwechselt Misstrauen mit Prüfung und urteilt über die Quelle statt über die Sache. Weitet man dieses Muster aus und tut ganze Forschungsfelder als „gekaufte Wissenschaft“ ab, kann es im Extremfall dazu führen, dass Menschen wirksame Behandlungen ablehnen. Entscheidend ist die Prüfung, nicht das Etikett. Ein Autoritätsargument läge vor, wenn er sich auf einen Experten berufen würde, das tut er aber nicht. Ebenso wenig beruft er sich auf eine Mehrheit. Und er verzerrt keine Aussage der Studie, denn über ihren Inhalt sagt er gar nichts.","coreRule":"⚡ Wer die Studie bezahlt hat, ist eine Frage an die Methode, kein Urteil über das Ergebnis.","beleg":"Werkstück G.2.4 (Red Flags; Kontext & Tiefe: Delegitimierung der Wissenschaft)","status":"entwurf","kurz":"Die Finanzierung ist ein guter Anlass, genauer hinzusehen, sagt aber nichts darüber, ob die Studie sauber gemacht wurde. Das zeigen erst Methodik und Ergebnisse. Wer pauschal ablehnt, urteilt über die Quelle statt über die Sache.","prueffrage":"Wie viele Teilnehmende hatte die Studie, gab es eine Vergleichsgruppe, und wer hat die Daten ausgewertet?","rueckmeldung":[{"option":0,"text":"Ein Urteil ohne Prüfung kann nach übernommener Meinung aussehen. Der Bekannte beruft sich aber auf keinen Experten oder eine Fachinstanz, sondern verwirft die Studie selbst und pauschal. Ein Autoritätsargument liegt hier nicht vor."},{"option":1,"text":"Der Spruch klingt wie eine weit verbreitete Haltung. In der Situation gibt es jedoch keinen Hinweis darauf, dass er sich auf eine Mehrheit stützt; er äußert sein eigenes, pauschales Urteil. Der Fehler liegt woanders."},{"option":2,"text":"Er lehnt die Studie ab, ohne sie zu kennen, das wirkt schnell unfair. Über ihren Inhalt sagt er aber gar nichts, also gibt er auch keine Aussage verzerrt wieder, um sie dann zu widerlegen."}],"familie":"inhalt-statt-absender","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Lundh, A. u. a. (2017): Industry sponsorship and research outcome. Cochrane Database of Systematic Reviews, MR000033","oeffentlich":true,"doi":"10.1002/14651858.MR000033.pub3","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8132492/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"9e51ac82abcb43fb"}},{"id":"qx-g-030","clusterId":"G","werkstueckRef":"G.2.4","stufe":4,"question":"Welcher Schritt in dieser Argumentation trägt nicht?","scenario":"Ein Beitrag schildert den gut dokumentierten Vioxx-Skandal: Ein Pharmaunternehmen hielt Hinweise auf Herzrisiken seines Schmerzmittels zu lange zurück. Daraus folgert der Beitrag: „Also unterdrückt die ganze Branche längst Heilmittel gegen Krebs.“","options":["Ein belegter Einzelfall wird zum Beweis für ein verdecktes Vorgehen der ganzen Branche erklärt (voreilige Verallgemeinerung).","Ein Experte wird als Beleg angeführt, obwohl allein die Autorität einer Person nichts beweist (Autoritätsargument).","Aus der zeitlichen Abfolge wird auf Ursache und Wirkung geschlossen, als hätte der Skandal das Verhalten der Branche bewirkt (Post hoc).","Die Kritik richtet sich gegen Personen statt gegen die Sache, sodass ein Angriff auf Verantwortliche den Beleg ersetzt (Ad hominem)."],"correctIndex":0,"explanation":"Die Branche hat einen wahren Kern, den man nicht wegreden muss: Sie ist profitorientiert, und es gibt nachgewiesenes Fehlverhalten. Ein belegter Missstand eines Unternehmens ist deshalb legitime Kritik. Der Fehler liegt im Sprung: Ein Einzelfall belegt den Einzelfall. Dass die ganze Branche Heilmittel gegen Krebs unterdrückt, folgt daraus nicht. Der reale Skandal dient hier als Hebel für die viel größere Verschwörungserzählung, dass „Big Pharma“ Heilmittel unterdrückt. Eine Autorität wird im Beitrag nicht angeführt, der Skandal ist schlicht ein Beispiel. Eine Ursache-Wirkung-Behauptung aus zeitlicher Abfolge steckt ebenfalls nicht darin, der Schluss geht vom Einzelfall auf die Branche. Und angegriffen wird das belegte Handeln eines Unternehmens, nicht eine Person.","coreRule":"⚡ Ein belegter Einzelfall trägt nur den Einzelfall, nicht ein ganzes System.","beleg":"Werkstück G.2.4 (Kontext & Tiefe; Anwendung & Relevanz: In Verschwörungsmythen; Schmiede-Übung)","status":"entwurf","kurz":"Der Vioxx-Fall belegt das Fehlverhalten eines Unternehmens, nicht ein Vorgehen der ganzen Branche. Der Fehler liegt im Sprung vom Einzelfall zur großen Verschwörungserzählung, obwohl die Kritik am Einzelfall berechtigt bleibt.","prueffrage":"Was genau zeigt der Vioxx-Fall, und was davon hat mit Krebsmitteln zu tun?","rueckmeldung":[{"option":1,"text":"Dass bloße Autorität nichts beweist, stimmt grundsätzlich. Im Beitrag beruft sich aber niemand auf eine Fachperson: Der Skandal dient als Beispiel, und hier hakt der Schluss an anderer Stelle."},{"option":2,"text":"Ein Zeitablauf liegt hier nicht zugrunde, und der Beitrag behauptet auch keine Ursache-Wirkung-Kette aus einer Reihenfolge. Der Schluss springt vielmehr von einem einzelnen Unternehmen auf die ganze Branche."},{"option":3,"text":"Einen Angriff auf Personen gibt es hier nicht. Kritisiert wird das belegte Handeln eines Unternehmens, und das ist berechtigt. Das Problem liegt erst darin, was daraus für die ganze Branche gefolgert wird."}],"familie":"verschwoerung-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Krumholz, H. M. u. a. (2007): What have we learnt from Vioxx? BMJ 334, 120–123","oeffentlich":true,"doi":"10.1136/bmj.39024.487720.68","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1779871/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"b89d7d803b0f2380"}},{"id":"qx-g-031","clusterId":"G","werkstueckRef":"G.3.1","stufe":1,"question":"Du prüfst die Werbung. Welche Rückfrage deckt am besten auf, ob die Rede von „Toxinen“ und „Schlacken“ überhaupt etwas Konkretes behauptet?","options":["Wurde die Kur mit einer Scheinkur verglichen, und wie unterschieden sich beide Gruppen am Ende?","Wie heißt jeder gemeinte Stoff chemisch, und wie wurde seine Menge vor und nach der Kur gemessen?","Welche Nebenwirkungen sind bei der Kur bekannt, und ab welcher Dauer gilt sie als bedenklich?","Wer verdient an der Kur, und wie unabhängig sind die Personen, die sie in der Werbung empfehlen?"],"correctIndex":1,"explanation":"Die Wörter klingen nach Wissenschaft, benennen aber keine bestimmte Substanz. „Toxin“ stammt aus der Toxikologie und wird hier zum Sammelbegriff für alles Unbestimmte, was als schädlich empfunden wird. „Schlacken“ stammt aus der Metallurgie und ist auf den Körper übertragen worden; biologisch gibt es sie nicht. Eine Behauptung ohne benennbaren Stoff lässt sich weder messen noch widerlegen. Die Rückfrage nach Name und Messung zwingt die Werbung, Konkretes zu liefern. Tatsächlich fand eine Übersichtsarbeit von 2015 für kommerzielle Detox-Diäten keine überzeugenden Belege, weder für die Ausscheidung von Toxinen noch für Gewichtsmanagement. Der Vergleich mit einer Scheinkur ist ein guter Test, setzt aber voraus, dass klar ist, was eigentlich gemessen werden soll. Fragen zu Nebenwirkungen sind für die Sicherheit wichtig, sagen aber nichts darüber, ob die behauptete Ausleitung etwas Bestimmtes meint. Wer an der Kur verdient, ist für die Glaubwürdigkeit der Werbung bedeutsam, benennt aber ebenfalls keinen Stoff.","coreRule":"⚡ Ein Begriff, der sich nicht chemisch benennen lässt, beschreibt keine Substanz, sondern ein Gefühl.","beleg":"Werkstück G.3.1 (Kontext & Tiefe: Pseudowissenschaftliche Umdeutung; Fn. gl-g-detox, Klein/Kiat 2015)","status":"entwurf","scenario":"Eine Werbeanzeige für eine „Detox-Saftkur“ verspricht, „Toxine und Schlacken“ auszuleiten, die sich durch Umwelt und Ernährung im Körper angesammelt hätten. Welche Stoffe genau gemeint sind, steht nirgends.","kurz":"Eine Behauptung ohne benennbaren Stoff lässt sich weder messen noch widerlegen. Nach Name und Messung zu fragen zwingt die Werbung, Konkretes zu liefern. „Toxine“ und „Schlacken“ klingen nach Wissenschaft, bleiben aber unbestimmt.","prueffrage":"Welchen einzigen Stoff aus der Anzeige könntest du morgen im Labor suchen lassen?","rueckmeldung":[{"option":0,"text":"Ein Vergleich mit einer Scheinkur ist grundsätzlich ein guter Test. Er setzt aber voraus, dass klar ist, was am Ende verglichen wird. Solange kein Stoff benannt ist, fehlt die Messgröße, und es gibt nichts, worin sich beide Gruppen unterscheiden könnten."},{"option":2,"text":"Für die Sicherheit sind Nebenwirkungen und Dauer wichtige Fragen. Sie klären aber nicht, ob mit „Toxinen“ und „Schlacken“ überhaupt etwas Bestimmtes gemeint ist. Eine Kur kann gut verträglich sein und trotzdem eine inhaltsleere Behauptung stützen."},{"option":3,"text":"Wer an der Kur verdient, ist für die Glaubwürdigkeit der Werbung bedeutsam. Der Blick auf Interessen und Unabhängigkeit benennt aber keinen Stoff und klärt nicht, was die Behauptung inhaltlich überhaupt aussagt."}],"familie":"begriff-messbar-machen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Verbraucherzentrale: Detox – überflüssig oder doch gesünder durch Entgiftung? (Stand 09.01.2026)","oeffentlich":true,"url":"https://www.verbraucherzentrale.de/wissen/lebensmittel/nahrungsergaenzungsmittel/detox-gesuender-durch-entgiftung-25381","abruf":"2026-10-12"},{"typ":"doi","kurz":"Klein, A. V.; Kiat, H. (2015): Detox diets for toxin elimination and weight management: a critical review of the evidence. Journal of Human Nutrition and Dietetics 28(6), 675–686","oeffentlich":false,"doi":"10.1111/jhn.12286"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"754097f66bfedf0d"}},{"id":"qx-g-032","clusterId":"G","werkstueckRef":"G.3.1","stufe":2,"question":"Was folgt aus deiner Beobachtung für die Behauptung, die Kur habe Giftstoffe aus deinem Körper ausgeleitet?","scenario":"Nach drei Tagen einer teuren Detox-Saftkur fühlst du dich leichter und „reiner“. Du hast dafür bezahlt, du glaubst an die Wirkung, und du hast drei Tage lang kaum etwas gegessen. Du fragst dich, ob dein gutes Gefühl beweist, dass die Kur Giftstoffe ausgeleitet hat.","options":["Nichts Verlässliches: Das Gefühl ist subjektiv und kann durch Erwartung entstehen, es zeigt nicht, welcher Stoff ausgeleitet wurde.","Es spricht für die Wirkung: Auch bei Medikamenten wurde oft erst eine Wirkung beobachtet und später ihr Mechanismus erklärt.","Es belegt die Wirkung wenigstens für dich: Wie du dich fühlst, kann nur du beurteilen, und dein Eindruck zählt daher als Beleg.","Es spricht gegen die Behauptung: Angesammelte Giftstoffe hätten sich schon vor der Kur bemerkbar machen müssen, wovon nichts bekannt ist."],"correctIndex":0,"explanation":"Ein gutes Gefühl ist ein schwacher Beleg: Wer Geld für eine Kur ausgibt und an sie glaubt, fühlt sich oft schon deshalb besser (Erwartungs- bzw. Placebo-Effekt). Dazu kommt, dass du drei Tage kaum etwas gegessen hast, und wer wenig isst, fühlt sich oft schon dadurch leichter. Um eine Ausleitung zu zeigen, müsste man den Stoff benennen und seine Konzentration vor und nach der Kur messen; ein Gefühl, auch ein lang anhaltendes, leistet das nicht. Schädliche Substanzen baut vor allem die Leber ohnehin ständig ab, und die Nieren scheiden viele davon aus. Eine Übersichtsarbeit von 2015 (Klein/Kiat) fand zu kommerziellen Detox-Diäten keine randomisierten kontrollierten Studien am Menschen und keine überzeugende Evidenz für die Ausleitung von Toxinen. Dass Wirkungen manchmal vor ihrem Mechanismus beobachtet wurden, stimmt, setzt aber eine verlässlich festgestellte Wirkung voraus, kein bloßes Gefühl. Dein Eindruck ist für dein Befinden maßgeblich, nicht aber dafür, was im Körper geschehen ist. Dass vorher keine Beschwerden erwähnt sind, beweist weder Giftstoffe noch ihr Fehlen, ohne Messung bleibt die Frage offen.","coreRule":"⚡ Ein gutes Gefühl nach einer Kur belegt nicht, dass ein Gift ausgeleitet wurde: Dafür braucht es einen benannten Stoff und eine Messung davor und danach.","beleg":"Werkstück G.3.1 (Red Flags; Verbindungen: Placebo); Fn. gl-g-detox (Klein/Kiat 2015, J Hum Nutr Diet 28(6), S. 675–686)","status":"entwurf","kurz":"Ein gutes Gefühl belegt keine Ausleitung: Wer zahlt und glaubt, fühlt sich oft schon deshalb besser, und wer kaum isst, fühlt sich leichter. Ob ein Stoff ausgeleitet wurde, zeigt erst eine Messung vorher und nachher.","prueffrage":"Was hast du in den drei Tagen außer den Säften anders gemacht als sonst, und wie fühlt sich das gewöhnlich an?","rueckmeldung":[{"option":1,"text":"Dass Wirkungen manchmal vor ihrem Mechanismus beobachtet wurden, stimmt. Dann stand aber eine verlässlich festgestellte Wirkung fest. Hier gibt es nur ein Gefühl, das Erwartung und Fasten bereits erklären."},{"option":2,"text":"Wie du dich fühlst, kannst nur du beurteilen, und das ist richtig. Es sagt aber nichts darüber, was im Körper geschehen ist. Ob Stoffe ausgeleitet wurden, zeigt kein Eindruck, sondern nur eine Messung."},{"option":3,"text":"Dass vorher keine Beschwerden bekannt sind, beweist weder Giftstoffe noch ihr Fehlen. Ohne Messung bleibt die Frage offen. Die Beobachtung belegt die Behauptung nicht, widerlegt sie aber auch nicht."}],"familie":"begriff-messbar-machen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Klein, A. V.; Kiat, H. (2015): Detox diets for toxin elimination and weight management: a critical review of the evidence. Journal of Human Nutrition and Dietetics 28(6), 675–686","oeffentlich":false,"doi":"10.1111/jhn.12286"},{"typ":"url","kurz":"Verbraucherzentrale: Detox – überflüssig oder doch gesünder durch Entgiftung? (Stand 09.01.2026)","oeffentlich":true,"url":"https://www.verbraucherzentrale.de/wissen/lebensmittel/nahrungsergaenzungsmittel/detox-gesuender-durch-entgiftung-25381","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"ea9986bb5a95f319"}},{"id":"qx-g-033","clusterId":"G","werkstueckRef":"G.3.1","stufe":3,"question":"Bei wem wird aus einer harmlosen Angewohnheit ein echtes Problem?","options":["Ein Mann trinkt drei Tage nur Säfte, weil er sich danach leichter fühlt, und geht anschließend wie geplant zur Kontrolle bei seinem Hausarzt.","Eine Frau hat seit Stunden Erbrechen und Krämpfe nach einem Pilzgericht und setzt auf eine Detox-Kur statt auf ärztliche Hilfe.","Eine Studentin gibt für die Kur mehr Geld aus als geplant und ärgert sich, weil sie nach drei Tagen vor allem hungrig war.","Eine Rentnerin mit Bluthochdruck trinkt täglich „Detox“-Tee und nimmt ihre verordneten Tabletten trotzdem unverändert weiter."],"correctIndex":1,"explanation":"Entscheidend ist nicht, ob jemand Geld ausgibt, ob ein Produkt wissenschaftlich klingt oder ob eine Kur unwirksam ist, sondern was sie ersetzt. Eine Saftkur, die man macht, weil man sich danach besser fühlt, bleibt meist harmlos: Das Gefühl ist echt, die behauptete „Entgiftung“ nicht, aber der Schaden ist gering. Gefährlich wird es, wenn ein unwirksames Produkt an die Stelle wirksamer Hilfe tritt. Bei einer realen Vergiftung zählt jede Stunde, und ein Produkt, dessen Wirkung über die natürliche Entgiftung durch Leber und Nieren hinaus nicht nachgewiesen ist, kostet dann Zeit, die für eine echte Behandlung fehlt. Der Mann geht trotz Kur zur ärztlichen Kontrolle, die Kur ersetzt also nichts. Der Ärger über Geld oder Hunger ist ein Verbraucherproblem, kein Gesundheitsrisiko. Die Frau mit Bluthochdruck nimmt ihre Tabletten weiter, der Tee tritt also nicht an die Stelle einer wirksamen Behandlung.","coreRule":"⚡ Harmlos ist das Ritual, gefährlich ist der Ersatz für echte Behandlung.","beleg":"Werkstück G.3.1 (Der Kipppunkt)","status":"entwurf","scenario":"Vier Personen nutzen „Detox“-Produkte, deren Anbieter versprechen, „Schlacken“ und Giftstoffe aus dem Körper auszuleiten.","kurz":"Problematisch wird ein unwirksames Produkt erst dort, wo es wirksame Hilfe ersetzt. Bei einer akuten Vergiftung geht dadurch Zeit verloren. Unwirksamkeit, Kosten oder wissenschaftlicher Anschein allein machen es nicht gefährlich.","prueffrage":"Was hätte jede der vier Personen ohne die Kur stattdessen getan, und was hätte ihr das gebracht?","rueckmeldung":[{"option":0,"text":"Die behauptete „Entgiftung“ ist unbelegt, daran ändert die Saftkur nichts. Hier aber geht der Mann wie geplant zur Kontrolle beim Hausarzt, die Kur ersetzt also keine Hilfe. Das gute Gefühl danach ist echt, der Schaden meist gering."},{"option":2,"text":"Mehr Geld ausgegeben und drei Tage gehungert zu haben, ist ärgerlich, die Kur hat sich für sie nicht gelohnt. Es ist aber ein Verbraucherproblem: Es geht weder eine Behandlung verloren noch droht ein größerer gesundheitlicher Schaden."},{"option":3,"text":"Ein Tee mit unbelegter Wirkung wirkt neben einer Erkrankung schnell verdächtig. Sie nimmt ihre verordneten Tabletten aber unverändert weiter, der Tee tritt also nicht an die Stelle der wirksamen Behandlung."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"NCCIH (NIH): Detoxes and Cleanses: What You Need To Know (Stand März 2025)","oeffentlich":true,"url":"https://www.nccih.nih.gov/health/detoxes-and-cleanses-what-you-need-to-know","abruf":"2026-10-12"},{"typ":"url","kurz":"Verbraucherzentrale: Detox – überflüssig oder doch gesünder durch Entgiftung? (Stand 09.01.2026)","oeffentlich":true,"url":"https://www.verbraucherzentrale.de/wissen/lebensmittel/nahrungsergaenzungsmittel/detox-gesuender-durch-entgiftung-25381","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"1d3e468e4a65982a"}},{"id":"qx-g-034","clusterId":"G","werkstueckRef":"G.3.1","stufe":4,"question":"Mit welchem einfachen Versuch prüfst du am besten, ob die Verfärbung wirklich ausgeleitete Giftstoffe zeigt?","scenario":"Eine Werbung verspricht: Ein Detox-Fußpflaster zieht über Nacht Giftstoffe aus dem Körper, am Morgen ist es dunkel verfärbt. Als „Beweis“ wird die braune Verfärbung gezeigt. Viele dieser Pflaster enthalten getrockneten Holzessig, der Feuchtigkeit anzieht.","options":["Das Pflaster auf einem frisch gewaschenen Fuß tragen: Fällt die Farbe schwächer aus, stammt sie von Schmutz statt von Giftstoffen.","Das Pflaster eine Nacht am Fuß und eine am Unterarm tragen: Färbt es sich an beiden Stellen, sind Giftstoffe überall im Körper.","Das Pflaster von jemandem tragen lassen, der seinen Zweck nicht kennt (Verblindung): Verfärbt es sich trotzdem, ist die Wirkung echt.","Ein unbenutztes Pflaster befeuchten und Wärme aussetzen: Verfärbt es sich auch ohne Fuß, beweist die Farbe nichts."],"correctIndex":3,"explanation":"Ein guter Test widerlegt nicht einfach die Behauptung, sondern baut eine einfache Alternativerklärung und prüft sie: Wenn die Verfärbung auch ohne Körper entsteht, kann sie kein Beleg für ausgeleitete Giftstoffe sein. Der Gegenversuch ist leicht durchführbar: ein paar Tropfen Wasser auf ein unbenutztes Pflaster, eine Tasse heißen Tee darauf stellen und zehn Minuten warten. Ein frisch gewaschener Fuß prüft nur, ob Schmutz mitspielt, nicht ob Feuchtigkeit allein die Farbe erzeugt. Am Fuß und am Unterarm färbt sich das Pflaster beide Male, weil auch dort Feuchtigkeit herankommt, über Giftstoffe sagt das nichts. Verblindung hilft gegen Erwartungseffekte, eine Farbe ist aber ohnehin sichtbar; offen bleibt die Alternativerklärung, nicht die Erwartung.","coreRule":"⚡ Baue die einfachste Alternativerklärung und teste sie, bevor du an eine Entgiftung glaubst.","beleg":"Werkstück G.3.1 (Werkbank-Frage; Red Flags); Fn. gl-g-6 (Goldacre 2008, Bad Science, Kap. 1 „Matter“)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Wenn sich ein unbenutztes Pflaster mit Feuchtigkeit und Wärme ebenfalls färbt, kann die Farbe keine ausgeleiteten Giftstoffe zeigen. Der Denkfehler liegt darin, die Behauptung nur zu bezweifeln, statt eine einfache Alternativerklärung gezielt zu testen.","prueffrage":"Welche Zutat des Pflasters könnte sich über Nacht auch ohne Giftstoffe verfärben, und wodurch?","rueckmeldung":[{"option":0,"text":"Schmutz als Farbquelle auszuschließen ist ein vernünftiger Gedanke. Er lässt aber offen, ob Feuchtigkeit allein die Farbe erzeugt, denn Schweiß gibt es auch am frisch gewaschenen Fuß."},{"option":1,"text":"Zwei Körperstellen zu vergleichen wirkt wie ein sauberer Versuch. Doch auch am Unterarm kommt Feuchtigkeit ans Pflaster, die Färbung an beiden Stellen sagt also nichts über Giftstoffe im Körper."},{"option":2,"text":"Verblindung schützt gegen Erwartungseffekte, doch eine Verfärbung sieht jeder, egal was er erwartet. Offen bleibt die Alternativerklärung, und dass sich das Pflaster färbt, beweist keine Wirkung."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"literatur","kurz":"Goldacre, B. (2008): Bad Science. London: Fourth Estate, Kap. 1 „Matter“ (dt. Die Wissenschaftslüge, 2010)","oeffentlich":false},{"typ":"url","kurz":"Federal Trade Commission (28.01.2009): FTC Charges Marketers of Kinoki Foot Pads With Deceptive Advertising","oeffentlich":true,"url":"https://www.ftc.gov/news-events/news/press-releases/2009/01/ftc-charges-marketers-kinoki-foot-pads-deceptive-advertising-seeks-funds-consumer-redress","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"3227af4be4d8c6c7"}},{"id":"qx-g-035","clusterId":"G","werkstueckRef":"G.3.2","stufe":1,"question":"Ein Homöopath sagt: „Wasser hat ein Gedächtnis. Ein Tropfen Ursubstanz hinterlässt in der Verdünnung seine Information, und die wirkt dann heilend.“ Welcher Einwand trifft die Behauptung am stärksten?","options":["Hätte Wasser ein perfektes Gedächtnis, trüge es auch die Informationen aus seiner ganzen früheren Geschichte; warum es sich nur an die letzte erinnern soll, bleibt unerklärt.","Wasser kann Informationen nur kurz behalten, sodass die Wirkung eines Mittels schon nach wenigen Minuten wieder verschwinden würde.","Wasser aus Kläranlagen ist stärker belastet als Quellwasser und eignet sich deshalb schlechter als Träger für die Information eines Mittels.","Ein Gedächtnis des Wassers kann nur in sehr verdünnten Lösungen entstehen und ist bei stärkeren Konzentrationen nicht mehr messbar."],"correctIndex":0,"explanation":"Das Wasser der Erde ist seit Jahrmillionen im Kreislauf und hatte unzählige Kontakte. Wer behauptet, es „erinnere“ sich ausgerechnet an die letzte „Information“ und vergesse alle anderen, muss einen Mechanismus nennen, der das Vergessen steuert; ohne ihn gilt die Behauptung nur für den einen Fall, den man gerade braucht. Der Einwand zur Dauer zielt physikalisch in eine richtige Richtung, denn Strukturen im flüssigen Wasser ordnen sich in Billionstelsekunden um, nicht erst nach Minuten; so formuliert räumt er aber ein, dass Wasser überhaupt Informationen speichert. Verschmutzung und Konzentration sind Nebenpunkte. Den Kern trifft nur der Widerspruch in einem Gedächtnis, das nichts vergisst und doch gezielt eine einzige Information trägt.","coreRule":"⚡ Ein Gedächtnis, das nichts vergisst, kann nicht gezielt eine einzige Information tragen.","beleg":"Werkstück G.3.2 (Die Wasserleiche; Aktivierungs-Frage)","status":"entwurf","scenario":"Das Wasser, aus dem ein homöopathisches Mittel hergestellt wird, war schon im Ozean, im Körper von Dinosauriern, in Kläranlagen, in Wolken, in Pflanzen und im Blut von Menschen. Es hat also unzählige Kontakte hinter sich. Jetzt wird es mit einem Tropfen Ursubstanz „informiert“.","kurz":"Hätte Wasser ein Gedächtnis, das nichts vergisst, trüge es die Spuren seiner ganzen Geschichte. Dass es nur die letzte „Information“ behält, braucht einen Mechanismus des Vergessens, und ohne den gilt die Behauptung nur dort, wo man sie braucht.","prueffrage":"Wie viele Stoffe hat dasselbe Wasser vor dem Tropfen schon berührt, und welche davon spielen in der Behauptung eine Rolle?","rueckmeldung":[{"option":1,"text":"Die Dauer ist ein ernster Punkt: Strukturen im Wasser ordnen sich sogar in Billionstelsekunden um. So formuliert räumt der Einwand aber ein, dass Wasser Informationen aufnimmt, und übergeht den Widerspruch, dass es auch alles Frühere tragen müsste."},{"option":2,"text":"Verschmutztes Wasser klingt tatsächlich nach schlechtem Träger. Doch auch Quellwasser hat eine lange Vorgeschichte voller Kontakte. Der Einwand löst das Kernproblem nicht und übernimmt die Annahme, Wasser könne Informationen speichern."},{"option":3,"text":"Dass nur bestimmte Verdünnungen wirken sollen, klingt nach einer plausiblen Bedingung. Es ist aber eine unbelegte Zusatzannahme und erklärt nicht, warum die frühere Geschichte des Wassers nicht stört. Der Kern der Behauptung bleibt unberührt."}],"familie":"zu-ende-denken","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Ball, P. (2004): The memory of water. Nature News, 08.10.2004","oeffentlich":true,"url":"https://www.nature.com/news/2004/041004/full/news041004-19.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Roth, K. (2013): Vitalisiert, verwirbelt, levitiert, energetisiert, informiert und anti-entropisch H2O – Jo mei! Chemie in unserer Zeit 47, 108–121","oeffentlich":false,"doi":"10.1002/ciuz.201300626"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c38a450ae559d5af"}},{"id":"qx-g-036","clusterId":"G","werkstueckRef":"G.3.2","stufe":2,"question":"Welches Ergebnis dieser Wiederholung würde die Behauptung „Wasser speichert Information“ am stärksten untergraben?","scenario":"Ein Bekannter verweist dich auf eine Veröffentlichung in „Nature“ von 1988. Ein französischer Forscher berichtete dort, stark verdünnte Antikörper wirkten noch auf weiße Blutzellen, und das soll belegen, dass Wasser ein „Gedächtnis“ hat. In seinem Labor wurde der Versuch anschließend wiederholt, diesmal mit Proben, deren Inhalt die Auswertenden nicht kannten (verblindet).","options":["Der Effekt verschwindet, wenn die Proben bei anderer Temperatur gelagert werden.","Der Effekt verschwindet, sobald die Auswertenden nicht wissen, welche Probe welche ist.","Der Effekt verschwindet, wenn man statt weißer Blutzellen eine andere Zellsorte untersucht.","Der Effekt bleibt bei verblindeter Auswertung erkennbar, fällt aber schwächer aus als zuvor."],"correctIndex":1,"explanation":"Wenn ein Effekt nur auftritt, solange die Auswertenden die Proben kennen, liegt die Ursache nahe bei den Erwartungen der Beobachter und nicht beim Wasser. Genau so verlief der Fall: Der Biomediziner Jacques Benveniste meldete 1988 in „Nature“ Effekte extrem verdünnter Antikörper auf weiße Blutzellen, doch bei der Nachprüfung in seinem Labor verschwand der Effekt, sobald die Proben verblindet ausgewertet wurden. Ein Befund, der davon abhängt, ob jemand die Probenzuordnung kennt, ist kein belastbarer Beleg für eine Eigenschaft des Wassers. Dagegen würde ein Effekt, der auch verblindet bestehen bleibt, die Behauptung stützen. Ein Effekt, der bei anderer Lagerung verschwindet, zeigt nur, dass er empfindlich ist, nicht dass er auf Erwartungen beruht. Dasselbe gilt für eine andere Zellsorte: Das schränkt höchstens ein, wo der Effekt auftritt. Ein verblindet bestehender, wenn auch schwächerer Effekt spricht eher für die Behauptung als gegen sie.","coreRule":"⚡ Ein Effekt, der verschwindet, wenn niemand weiß, welche Probe welche ist, trägt keine Theorie.","beleg":"Werkstück G.3.2 (Kontext & Tiefe: Unfalsifizierbarkeit); Fn. gl-g-4 (Davenas u. a. 1988, Nature 333, S. 816–818; Maddox/Randi/Stewart 1988, Nature 334, S. 287–290)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Hängt ein Effekt davon ab, ob die Auswertenden die Proben kennen, liegt die Ursache bei deren Erwartungen und nicht beim Wasser. Dass er unter bestimmten Bedingungen empfindlich ist oder nur bei einer Zellsorte auftritt, widerlegt das nicht.","prueffrage":"Mit welchem Ergebnis der Wiederholung wäre zu rechnen, wenn das Wasser in Wahrheit gar nichts speichert?","rueckmeldung":[{"option":0,"text":"Ein Effekt, der empfindlich auf die Lagerung reagiert, ist noch kein Hinweis auf Fehler. Er zeigt nur, dass er an Bedingungen geknüpft ist. Ob die Erwartungen der Auswertenden ihn erzeugen, bleibt dabei völlig offen."},{"option":2,"text":"Tritt der Effekt nur bei einer Zellsorte auf, wird sein Geltungsbereich enger. Dass er auf Täuschung durch Erwartungen beruht, folgt daraus nicht, und die Behauptung wäre damit höchstens eingegrenzt, nicht entkräftet."},{"option":3,"text":"Ein schwächerer Effekt ist vor allem ein Hinweis, die Stärke genauer zu prüfen. Er bleibt aber auch ohne Kenntnis der Probenzuordnung sichtbar, und gerade das spräche eher für die Behauptung als gegen sie."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Ball, P. (2004): The memory of water. Nature News, 08.10.2004","oeffentlich":true,"url":"https://www.nature.com/news/2004/041004/full/news041004-19.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Davenas, E. u. a. (1988): Human basophil degranulation triggered by very dilute antiserum against IgE. Nature 333, 816–818","oeffentlich":false,"doi":"10.1038/333816a0"},{"typ":"doi","kurz":"Maddox, J.; Randi, J.; Stewart, W. W. (1988): „High-dilution“ experiments a delusion. Nature 334, 287–290","oeffentlich":false,"doi":"10.1038/334287a0"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"af85a10da1a09cdb"}},{"id":"qx-g-037","clusterId":"G","werkstueckRef":"G.3.2","stufe":3,"question":"Was ist an der Antwort des Beraters der entscheidende Denkfehler?","options":["Die Behauptung wird erst nachträglich eingeführt, um den Widerspruch zur fehlenden Substanz abzufangen, und lässt sich mit keinem Instrument prüfen.","Die Behauptung schließt aus einer Besserung nach der Einnahme auf die Wirkung des Mittels, obwohl beides nur zeitlich zusammenfällt (Post hoc).","Die Behauptung stützt sich darauf, dass viele Menschen das Mittel anwenden, obwohl die Verbreitung eines Mittels nichts über seine Wirkung sagt.","Die Behauptung nennt das Mittel natürlich und schließt daraus auf seine Wirksamkeit, obwohl natürlich nicht automatisch wirksam bedeutet."],"correctIndex":0,"explanation":"Die Zusatzannahme „Information im Wasser“ wurde nicht aus Beobachtungen abgeleitet, sondern soll nur den Widerspruch auflösen, dass in stark verdünnten Mitteln (jenseits von etwa C12) kein Molekül der Substanz mehr enthalten ist. Solange diese Information mit keinem Instrument gemessen werden kann, ist die Behauptung unfalsifizierbar. Wo sie doch einmal prüfbar gemacht wurde, hielt sie nicht: Jacques Benveniste meldete 1988 in „Nature“, extrem verdünnte Antikörper wirkten noch auf weiße Blutzellen, doch bei der Nachprüfung verschwand der Effekt, sobald die Proben verblindet ausgewertet wurden. Dazu kommt, dass Wasserstoffbrücken zwischen Wassermolekülen sich im Femto- bis Pikosekundenbereich bilden und lösen, Struktur in Flüssigkeiten ist also extrem kurzlebig. Und warum sollte sich das Wasser ausgerechnet an diese eine Substanz erinnern und alle anderen Stoffe aus seiner langen Geschichte vergessen? Von einer Besserung nach der Einnahme ist im Gespräch gar nicht die Rede, ein Post-hoc-Schluss liegt also nicht vor. Auch auf die Verbreitung des Mittels oder darauf, dass es natürlich sei, beruft sich der Berater nicht.","coreRule":"⚡ Eine Zusatzannahme, die nur den Widerspruch abfängt und sich nicht prüfen lässt, ist noch keine Erklärung.","beleg":"Werkstück G.3.2 (Kernidee; Kontext & Tiefe; Verbindungen); Fn. gl-g-5 (Roth 2013, Chemie in unserer Zeit 47, S. 111)","status":"entwurf","scenario":"Eine Kundin fragt in einer Apotheke, wie ein Mittel in der Potenz C30 wirken soll, wenn rechnerisch kein Molekül des Wirkstoffs mehr enthalten ist. Der Berater antwortet: „Das Wasser hat sich die Information gemerkt. Die Wirkung ist eben immateriell.“","kurz":"Die „Information im Wasser“ wird erst erfunden, um den Widerspruch zur fehlenden Substanz zu überbrücken, und ist mit keinem Instrument messbar. Wer eine Annahme so schützt, macht sie unprüfbar und damit unfalsifizierbar.","prueffrage":"Auf welche Frage der Kundin antwortet der Berater, und welche Beobachtung nennt er als Grundlage für seine Antwort?","rueckmeldung":[{"option":1,"text":"Post-hoc-Schlüsse sind bei Mitteln dieser Art verbreitet, und der Fehler ist real. Im Gespräch fehlt aber jede Besserung nach der Einnahme: Der Berater weicht der Frage nach der fehlenden Substanz aus, statt aus einem Verlauf auf eine Wirkung zu schließen."},{"option":2,"text":"Dass Verbreitung nichts über Wirkung sagt, stimmt, und ein solches Argument hört man bei diesen Mitteln oft. Der Berater beruft sich aber gar nicht auf viele Anwender, sondern antwortet mit einer Zusatzannahme über das Wasser."},{"option":3,"text":"„Natürlich“ ist tatsächlich kein Beleg für Wirksamkeit. Der Berater nennt das Mittel aber weder natürlich noch leitet er daraus etwas ab. Sein Fehler liegt im Umgang mit dem Einwand der fehlenden Substanz."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Ball, P. (2004): The memory of water. Nature News, 08.10.2004","oeffentlich":true,"url":"https://www.nature.com/news/2004/041004/full/news041004-19.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Rademacher, P. (2013): Die Mär vom Wasser mit Gedächtnis. Chemie in unserer Zeit 47(1), 24–31","oeffentlich":false,"doi":"10.1002/ciuz.201300580"},{"typ":"doi","kurz":"Roth, K. (2013): Vitalisiert, verwirbelt, levitiert, energetisiert, informiert und anti-entropisch H2O – Jo mei! Chemie in unserer Zeit 47, 108–121","oeffentlich":false,"doi":"10.1002/ciuz.201300626"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"9e1c49442d5d31b8"}},{"id":"qx-g-038","clusterId":"G","werkstueckRef":"G.3.2","stufe":4,"question":"Was ist an dieser Gesprächsführung des Anbieters fehlerhaft?","scenario":"Eine Anzeige für ein „informiertes“ Trinkwassergerät verspricht, es speichere „positive Schwingungen“. Auf die Frage nach einem Messverfahren heißt es: „Die Wirkung ist feinstofflich – du denkst zu materialistisch.“","options":["Er verspricht eine Wirkung, ohne einen prüfbaren Mechanismus zu nennen, und weicht der Nachfrage mit einem Spruch aus.","Er nennt kein einziges Toxin beim Namen, obwohl er ein Gerät zur Wasserreinigung verkauft.","Er deutet an, dass alle kritischen Studien zu seinem Gerät von der Konkurrenz bezahlt seien.","Er teilt die Kundschaft in Erwachte und Schlafende ein und wertet Zweifler pauschal ab."],"correctIndex":0,"explanation":"Eine Wirkbehauptung ist nur dann prüfbar, wenn sie sagt, wie die Wirkung zustande kommen soll und woran man sie messen könnte. „Positive Schwingungen“ werden ohne Speicher- und Abrufmechanismus versprochen und als „feinstofflich“ beschrieben, damit sie sich jeder Messung entziehen. Auf die berechtigte Nachfrage kommt kein Beleg, sondern ein Spruch: „Du denkst zu materialistisch“ ist ein Gedanken-stoppendes Klischee, das die Frage abwürgt, statt sie zu beantworten. Genau diese Antwort ist ein typisches Warnsignal der „Wassergedächtnis“-Rhetorik. Das Muster lässt sich so anwenden: Wer eine Wirkung behauptet, trägt die Beweislast und muss zeigen, wie sich die Wirkung nachweisen lässt. Ohne Mechanismus und Messbarkeit bleibt „Information“ ein Wort ohne Gegenstand. Die anderen Optionen treffen den Kern nicht: Die fehlende Nennung von Toxinen, der Verweis auf bezahlte Studien und die Einteilung in Erwachte und Schlafende kommen in der Anzeige entweder gar nicht vor oder sind höchstens Begleitwirkung. Fehlerhaft im Kern ist, dass Mechanismus und Messbarkeit verweigert und die Behauptung so gegen Prüfung abgeschirmt wird.","coreRule":"⚡ Ohne Mechanismus und Messbarkeit bleibt „Information“ ein Wort ohne Gegenstand.","beleg":"Werkstück G.3.2 (Red Flags)","status":"entwurf","kurz":"Eine Wirkung ist nur prüfbar, wenn gesagt wird, wie sie zustande kommt und woran man sie misst. Hier ersetzt ein Spruch den Beleg, und „feinstofflich“ entzieht die Behauptung jeder Messung, obwohl der Anbieter die Beweislast trägt.","prueffrage":"Woran könnte man hier überhaupt feststellen, ob das Gerät etwas bewirkt oder nicht?","rueckmeldung":[{"option":1,"text":"Bei einem Wassergerät erwartet man vielleicht Aussagen zu Schadstoffen. Die Anzeige verspricht aber keine Reinigung, sondern „positive Schwingungen“. Fehlerhaft ist, dass auf die Frage nach einem Messverfahren nur ein Spruch statt eines Belegs kommt."},{"option":2,"text":"Der Verdacht, Kritik sei gekauft, ist ein bekanntes Ausweichmuster. In diesem Gespräch fällt er aber nicht: Der Anbieter sagt nichts über Studien oder Konkurrenz. Er weicht der Nachfrage nach einem Messverfahren auf andere Weise aus."},{"option":3,"text":"Der Satz „du denkst zu materialistisch“ wertet den Fragenden tatsächlich ab. Das ist aber nur eine Begleiterscheinung: Von Erwachten und Schlafenden ist nicht die Rede. Der Kern liegt darin, dass Mechanismus und Messbarkeit verweigert werden."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Ball, P. (2004): The memory of water. Nature News, 08.10.2004","oeffentlich":true,"url":"https://www.nature.com/news/2004/041004/full/news041004-19.html","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"ebf86606b389f618"}},{"id":"qx-g-039","clusterId":"G","werkstueckRef":"G.3.3","stufe":1,"question":"Du liest die Aussage: „Ich setze auf natürliche Immunität statt auf Impfung.“ Was leistet das Wort „natürlich“ in diesem Satz vor allem?","options":["Es lässt die Infektion als reinen, ursprünglichen Weg erscheinen und blendet die Risiken der Krankheit dabei einfach aus.","Es zeigt an, dass der Weg wissenschaftlich geprüft ist, weil nur unter Alltagsbedingungen erprobte Verfahren als verlässlich gelten.","Es stellt beide Wege als gleichwertig dar, sodass die Wahl nur noch Geschmackssache ist und kein Weg abgewertet wird.","Es verweist auf die lange Entwicklung des Immunsystems und belegt damit, dass eine Infektion den bestmöglichen Schutz liefert."],"correctIndex":0,"explanation":"Das Wort „natürlich“ weckt ein positives Gefühl (Appell an die Natur): Die Infektion wirkt wie ein reiner, ursprünglicher Prozess, die Impfung wie ein künstlicher Eingriff in ein „perfektes“ Immunsystem. Das Narrativ konzentriert sich nur auf das Ergebnis (Immunität) und blendet den Prozess, die potenziell tödliche Krankheit, aus. Dass „natürlich“ nicht „besser“ heißt, zeigt Tetanus: Bei Tetanus führt die Infektion zu keiner Immunität, die Impfung schon. Bei HPV erzeugt die Impfung eine stärkere und verlässlichere Immunantwort als die Infektion. Ob ein Weg gut ist, entscheiden Risiken und Schutz, nicht der Klang des Wortes.","coreRule":"⚡ „Natürlich“ ist ein Gefühlswort und kein Qualitätsnachweis.","beleg":"Werkstück G.3.3 (Kontext & Tiefe: Appell an die Natur; Red Flags: Herdenimmunität)","status":"entwurf","scenario":"In einer Diskussion über Impfungen sagt jemand: „Ich setze lieber auf die natürliche Immunität. Das ist der echte Weg, nicht dieser künstliche Eingriff.“","kurz":"„Natürlich“ weckt ein gutes Gefühl: Die Infektion wirkt ursprünglich und rein, die Impfung wie ein Eingriff. So rückt nur das Ergebnis Immunität ins Bild, die möglicherweise gefährliche Krankheit davor verschwindet.","prueffrage":"Wie wirkt der Satz, wenn man „natürliche Immunität“ durch „Immunität nach Ansteckung“ ersetzt?","rueckmeldung":[{"option":1,"text":"Dass „natürlich“ nach Verlässlichkeit klingt, stimmt. Geprüft ist damit aber nichts: Das Wort wirkt über ein Gefühl, nicht über Belege. Ob ein Weg gut ist, entscheiden Risiken und Schutz, nicht der Klang des Wortes."},{"option":2,"text":"Der Satz stellt die Wege nicht gleich, er wertet sie gegeneinander: Die Infektion ist der „echte Weg“, die Impfung ein „künstlicher Eingriff“. Das Wort „natürlich“ verteilt also Lob und Abwertung, statt eine bloße Geschmacksfrage offen zu lassen."},{"option":3,"text":"Das Immunsystem hat sich tatsächlich über lange Zeit entwickelt, doch daraus folgt nicht der beste Schutz durch Infektion. Bei Tetanus bringt die Infektion keine Immunität, die Impfung schon, und bei HPV wirkt die Impfung stärker und verlässlicher."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"CDC: Epidemiology and Prevention of Vaccine-Preventable Diseases („Pink Book“), Kap. 21 Tetanus","oeffentlich":true,"url":"https://www.cdc.gov/pinkbook/hcp/table-of-contents/chapter-21-tetanus.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Ghilencea, B. u. a. (2026): Natural Versus Vaccine-Induced Immunity Against HPV. Antibodies 15(4), 61","oeffentlich":true,"doi":"10.3390/antib15040061","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13398047/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c04e020ea04bb868"}},{"id":"qx-g-040","clusterId":"G","werkstueckRef":"G.3.3","stufe":2,"question":"Was ist an dieser Argumentation grundlegend falsch?","scenario":"In einer Diskussion über Impfungen sagt jemand: „Wer Tetanus durchmacht, hat danach natürliche Immunität. Das ist doch der beste Weg, die Impfung brauche ich nicht.“ Du weißt: Das Tetanus-Toxin ist schon in winzigen Mengen tödlich, und eine überstandene Erkrankung hinterlässt keinen Schutz vor einer neuen Ansteckung.","options":["Sie setzt voraus, dass die Erkrankung Schutz hinterlässt; bei Tetanus tut sie das nicht, die Impfung schon, und der „natürliche“ Weg ist hier gefährlicher und nutzlos.","Sie bezieht sich auf einen Einzelfall und verallgemeinert ihn auf alle Menschen (Anekdote), obwohl einzelne Verläufe nichts über Wahrscheinlichkeiten aussagen.","Sie beruft sich darauf, dass viele Menschen ohne Impfung gesund bleiben (Mitläufer-Argument), obwohl die Verbreitung einer Haltung nichts beweist.","Sie greift Ärzte und Hersteller persönlich an, statt auf Argumente einzugehen (Ad hominem), sodass vermutete Motive an die Stelle von Belegen und Gründen treten."],"correctIndex":0,"explanation":"Das Argument setzt stillschweigend voraus, dass „natürlich“ zugleich „besser“ heißt und dass eine Erkrankung überhaupt Schutz hinterlässt. Beides lässt sich prüfen: Tetanus-Gift ist so stark, dass schon winzige Mengen (geschätzte minimale tödliche Dosis: 2,5 Nanogramm je Kilogramm Körpergewicht) tödlich wirken können. Laut CDC hinterlässt die Erkrankung keine Tetanus-Immunität. Wer sie überlebt, ist deshalb nicht geschützt; nach der Erkrankung soll die Impfung beginnen oder fortgesetzt werden, sobald sich der Zustand stabilisiert hat (CDC). Die Impfung bringt den Schutz, den die Infektion nicht liefert. Bei HPV ist die natürliche Immunität zwar vorhanden, aber schwächer als die Impf-Immunität; bei Tetanus entsteht sie gar nicht. Ob Infektion oder Impfung besser schützt, muss man pro Krankheit prüfen. Von einem Einzelfall, auf den sich die Aussage stützt, ist keine Rede, sie macht eine allgemeine Behauptung über Immunität. Auf eine Mehrheit beruft sie sich ebenfalls nicht. Und Personen werden nicht angegriffen, es geht um die Sache.","coreRule":"⚡ „Natürlich“ heißt nicht „besser“: Prüfe pro Krankheit, ob die Infektion überhaupt schützt, und was der Weg dorthin kostet.","beleg":"Werkstück G.3.3 (Kontext & Tiefe: Schaffung einer falschen Sicherheit); Fn. gl-g-2 (CDC, Pink Book, 14. Aufl. 2021, Kap. 21)","status":"entwurf","kurz":"Die Aussage setzt voraus, dass Erkrankung Schutz hinterlässt und „natürlich“ besser sei. Bei Tetanus stimmt beides nicht: Das Gift ist schon in winzigen Mengen tödlich, und wer überlebt, ist trotzdem nicht geschützt.","prueffrage":"Was bleibt nach einer überstandenen Tetanus-Erkrankung an Schutz zurück, und wie riskant ist der Weg dorthin?","rueckmeldung":[{"option":1,"text":"Dass einzelne Verläufe wenig über Wahrscheinlichkeiten sagen, stimmt als Grundsatz. Hier aber wird kein Einzelfall erzählt: Die Aussage behauptet allgemein, eine Erkrankung hinterlasse Immunität, und genau diese Voraussetzung trägt nicht."},{"option":2,"text":"Dass die Verbreitung einer Haltung nichts beweist, gilt allgemein. In der Aussage beruft sich aber niemand darauf, was viele andere tun; sie stützt sich auf die angebliche Schutzwirkung der Erkrankung, und die gibt es bei Tetanus nicht."},{"option":3,"text":"Ein persönlicher Angriff wäre ein klassischer Fehlschluss, kommt hier aber nicht vor: Weder Ärzte noch Hersteller werden erwähnt, die Aussage macht eine Sachbehauptung. Diese lässt sich prüfen, und die Prüfung zeigt, dass sie nicht stimmt."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"CDC: Epidemiology and Prevention of Vaccine-Preventable Diseases („Pink Book“), Kap. 21 Tetanus","oeffentlich":true,"url":"https://www.cdc.gov/pinkbook/hcp/table-of-contents/chapter-21-tetanus.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Ghilencea, B. u. a. (2026): Natural Versus Vaccine-Induced Immunity Against HPV. Antibodies 15(4), 61","oeffentlich":true,"doi":"10.3390/antib15040061","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13398047/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"f6edf3d022e1d72b"}},{"id":"qx-g-041","clusterId":"G","werkstueckRef":"G.3.3","stufe":3,"question":"Wie lässt sich der Unterschied zwischen Tetanus und HPV beim Vergleich von „natürlicher“ und Impf-Immunität am genauesten beschreiben?","options":["Bei Tetanus entsteht nach der Krankheit gar kein Schutz, bei HPV ein Schutz, der schwächer und unzuverlässiger ist als der Impfschutz.","Bei beiden Krankheiten entsteht nach der Infektion gar kein Schutz, und der einzige Unterschied liegt in der Schwere der Erkrankung.","Bei Tetanus entsteht nach der Krankheit gar kein Schutz, bei HPV ein Schutz, der stärker und zuverlässiger ist als der Impfschutz.","Bei beiden Krankheiten ist der Schutz nach der Infektion schwächer als der Impfschutz, hält aber deutlich länger an als dieser."],"correctIndex":0,"explanation":"Das Beispiel zeigt, dass es „die“ natürliche Immunität nicht gibt, sondern dass sie je nach Krankheit sehr unterschiedlich ausfällt. Bei Tetanus hinterlässt die Erkrankung laut CDC keine Immunität; der Grund ist die extreme Giftigkeit des Toxins (die geschätzte minimale tödliche Dosis liegt bei 2,5 Nanogramm je Kilogramm Körpergewicht). Deshalb soll auch nach überstandener Krankheit geimpft werden. Bei HPV bildet der Körper nach einer Infektion zwar Antikörper, aber langsam, unvollständig und typspezifisch. Die Impfung erzeugt deutlich höhere Antikörperspiegel (in einer Übersicht 3.000–10.000 mMU/mL gegenüber 100–500 mMU/mL nach natürlicher Ansteckung), und der Impfschutz hält nach bisherigen Daten über ein Jahrzehnt an. „Gar keinen Schutz“ bei HPV zu behaupten wäre übertrieben, „stärker als die Impfung“ wäre falsch. Wer verallgemeinert („immer besser“), übersieht diese Unterschiede zwischen Krankheiten.","coreRule":"⚡ Pauschalaussagen wie „natürlich ist immer besser“ prüfst du Krankheit für Krankheit: Mal fehlt der natürliche Schutz ganz, mal ist er nur schwächer als der Impfschutz.","beleg":"Werkstück G.3.3 (Kontext & Tiefe: Schaffung einer falschen Sicherheit); Fn. gl-g-3 (Ghilencea u. a. 2026, Antibodies 15(4), 61)","status":"entwurf","scenario":"In einer Diskussion sagt jemand: „Natürliche Immunität ist immer besser als eine Impfung.“ Als Gegenargument werden zwei Krankheiten genannt: Tetanus und HPV.","kurz":"Bei Tetanus hinterlässt die Krankheit keinen Schutz, bei HPV nur einen schwachen, langsam aufgebauten und typspezifischen, der an den Impfschutz nicht heranreicht. Der Fehler liegt im „immer“: Natürliche Immunität fällt je nach Krankheit sehr verschieden aus.","prueffrage":"Was bleibt nach überstandener Krankheit jeweils an Schutz zurück, bei Tetanus und bei HPV, und wie verhält sich das zum Impfschutz?","rueckmeldung":[{"option":1,"text":"„Gar kein Schutz“ trifft auf Tetanus zu, ist bei HPV aber übertrieben: Nach einer Infektion bildet der Körper Antikörper, nur langsam und unvollständig. Der Unterschied liegt darin, ob und wie viel Schutz entsteht, nicht in der Schwere."},{"option":2,"text":"Für Tetanus stimmt das, bei HPV ist die Richtung aber vertauscht: Der Schutz nach Ansteckung ist schwächer und unzuverlässiger als der Impfschutz. Ein stärkerer natürlicher Schutz würde „natürlich ist immer besser“ sogar stützen."},{"option":3,"text":"Bei HPV ist der Schutz nach Infektion tatsächlich schwächer als nach Impfung. Bei Tetanus fehlt er aber ganz, und dass natürlicher Schutz länger hält, ist nicht belegt; belegt ist ein Impfschutz gegen HPV über mehr als ein Jahrzehnt."}],"familie":"genau-unterscheiden","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"CDC: Epidemiology and Prevention of Vaccine-Preventable Diseases („Pink Book“), Kap. 21 Tetanus","oeffentlich":true,"url":"https://www.cdc.gov/pinkbook/hcp/table-of-contents/chapter-21-tetanus.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Ghilencea, B. u. a. (2026): Natural Versus Vaccine-Induced Immunity Against HPV: A Comparative Review of Antibody Response and Cancer Prevention. Antibodies 15(4), 61","oeffentlich":true,"doi":"10.3390/antib15040061","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13398047/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"3154856dff33f73b"}},{"id":"qx-g-042","clusterId":"G","werkstueckRef":"G.3.3","stufe":4,"question":"Welche Schlussfolgerung ist angemessen?","options":["Der hohe Schutz gilt nur für Menschen, die die Infektion überlebt haben; Tote und Komplikationen auf dem Weg dorthin fehlen in den Zahlen.","Die Aussage stützt sich auf Einzelfälle statt auf Daten; erst eine größere Zahl untersuchter Menschen würde einen solchen Schluss tragen.","Die hohen Schutzwerte sind überhöht, weil Extremwerte bei einer erneuten Auswertung zur Mitte zurückfallen; die 78 Prozent werden also sinken.","Die beiden Zahlen widersprechen sich; wenn Studien so unterschiedlich hohe Werte liefern, kann keine der beiden als verlässlich gelten."],"correctIndex":0,"explanation":"Die Zahlen beschreiben den Schutz derjenigen, die die Infektion überlebt haben. Wer daran gestorben ist, taucht in dieser Gruppe nicht auf, und was die erste Erkrankung an Komplikationen gekostet hat, steckt in keiner der Prozentzahlen: Das ist die Perspektive des Überlebensirrtums. Der hohe Schutz vor schwerem Verlauf ist real, wurde aber mit der Krankheit selbst bezahlt, und vor erneuter Ansteckung schützte die Infektion deutlich schlechter. Dass Beobachtungsstudien Störfaktoren enthalten können, mindert die Aussagekraft, macht sie aber nicht wertlos. Wer Wege vergleicht, muss deshalb auch die Kosten des Weges betrachten und nicht nur das Ergebnis am Ziel. Die anderen Gedanken klingen vernünftig, passen aber nicht: Hier stehen die Ergebnisse von 65 Studien, keine Einzelfälle. Die beiden Zahlen messen verschiedene Ereignisse (schwerer Verlauf, erneute Ansteckung) und widersprechen sich deshalb nicht. Dass Extremwerte zur Mitte zurückfallen, gilt für ausgewählte Ausreißer, nicht für eine Auswertung über viele Studien.","coreRule":"⚡ Ein Schutz, der mit der Krankheit bezahlt wird, ist nicht umsonst, auch wenn er hoch ist.","beleg":"Werkstück G.3.3 (Anwendung & Relevanz: COVID-19-Pandemie; Verbindungen: Überlebensirrtum); Fn. gl-g-reinfektion (COVID-19 Forecasting Team 2023, The Lancet 401, S. 833 und 841)","status":"entwurf","scenario":"Eine Auswertung von 65 Beobachtungsstudien zeigt: Menschen, die eine COVID-19-Infektion überstanden hatten, waren später zu mehr als 78 Prozent vor schwerem Verlauf geschützt, vor erneuter Ansteckung mit Omikron BA.1 aber nur zu rund 45 Prozent. Jemand sagt dazu: „Da seht ihr es: Wer die Krankheit durchmacht, ist hinterher bestens geschützt. Die Impfung brauche ich nicht.“","kurz":"Die Prozentzahlen beschreiben nur Menschen, die die Infektion überlebt haben. Wer daran starb oder Folgen davontrug, fehlt in den Zahlen. Wer die Wege vergleicht, muss auch ihre Kosten betrachten, nicht nur das Ergebnis am Ziel.","prueffrage":"Wovor schützte die überstandene Infektion laut den Zahlen gut, wovor weniger gut, und was macht die Person daraus?","rueckmeldung":[{"option":1,"text":"Einzelfälle allein würden einen solchen Schluss tatsächlich nicht tragen. Hier liegen aber die Ergebnisse von 65 Studien vor. Das Problem sind nicht zu wenige Daten, sondern wer in ihnen fehlt: Mehr Untersuchte änderten daran nichts."},{"option":2,"text":"Dass Extremwerte beim erneuten Messen zur Mitte zurückfallen, trifft auf ausgewählte Ausreißer zu. Eine Auswertung über viele Studien ist keine solche Auswahl, und der Schutz vor schwerem Verlauf gilt als real. Fraglich ist nicht die Höhe der Zahl, sondern was sie verschweigt."},{"option":3,"text":"Die Zahlen widersprechen sich nicht, denn sie messen verschiedene Ereignisse: schwerer Verlauf auf der einen, erneute Ansteckung mit Omikron BA.1 auf der anderen Seite. Beobachtungsstudien haben Grenzen, sind deshalb aber nicht unbrauchbar."}],"familie":"nutzen-und-risiko-abwaegen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"COVID-19 Forecasting Team (2023): Past SARS-CoV-2 infection protection against re-infection: a systematic review and meta-analysis. The Lancet 401(10379), 833–842","oeffentlich":true,"doi":"10.1016/S0140-6736(22)02465-5","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9998097/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"ba5ce4486635816f"}}]`);export{t as n,n as t};